    vehicles: ['rust_reaper'],
    equipped: 'rust_reaper',
    career: { defeated: [], current: 0 },
    completed: {},
    missionWins: 0,
    series: null,
    settings: { ...DEFAULT_SETTINGS }
  }
}

function safeParse(raw, fallback) {
  try {
    return raw ? JSON.parse(raw) : fallback
  } catch {
    return fallback
  }
}

export class SaveStore {
  constructor() {
    this.state = safeParse(localStorage.getItem(STORE_KEY), null)
    if (!this.state || !Array.isArray(this.state.profiles)) {
      this.state = { profiles: [], currentProfileId: null }
    }
    this.slots = safeParse(localStorage.getItem(SLOT_KEY), [null, null, null])
  }

  persist() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(this.state))
      localStorage.setItem(SLOT_KEY, JSON.stringify(this.slots))
    } catch (e) {
      console.warn('Save failed', e)
    }
  }

  profiles() {
    return [...this.state.profiles].sort((a, b) => (b.lastActive || 0) - (a.lastActive || 0))
  }

  profile() {
    const id = this.state.currentProfileId
    return this.state.profiles.find(p => p.id === id) || null
  }

  create(fields) {
    const p = freshProfile(fields)
    this.state.profiles.push(p)
    this.state.currentProfileId = p.id
    this.persist()
    return p
  }

  login(id) {
    const p = this.state.profiles.find(p => p.id === id)
    if (!p) return null
    p.lastActive = Date.now()
    this.state.currentProfileId = p.id
    this.persist()
    return p
  }

  logout() {
    this.state.currentProfileId = null
    this.persist()
  }

  remove(id) {
    this.state.profiles = this.state.profiles.filter(p => p.id !== id)
    if (this.state.currentProfileId === id) this.state.currentProfileId = null
    this.persist()
  }

  update(patch = {}) {
    const p = this.profile()
    if (!p) return null
    Object.assign(p, patch)
    p.lastActive = Date.now()
    this.persist()
    return p
  }

  updateSettings(patch) {
    const p = this.profile()
    if (!p) return
    p.settings = { ...DEFAULT_SETTINGS, ...(p.settings || {}), ...patch }
    this.persist()
    return p.settings
  }

  addReward(money, xp) {
    const p = this.profile()
    if (!p) return
    p.money += Math.max(0, Math.round(money))
    p.xp += Math.max(0, Math.round(xp))
    const newLevel = Math.max(1, Math.floor(Math.sqrt(p.xp / 250)) + 1)
    p.level = Math.min(newLevel, 99)
    this.persist()
    return p
  }

  saveSlot(index) {
    const p = this.profile()
    if (!p) return false
    this.slots[index] = {
      savedAt: Date.now(),
      name: p.name,
      level: p.level,
      money: p.money,
      profile: JSON.parse(JSON.stringify(p))
    }
    this.persist()
    return true
  }

  loadSlot(index) {
    const slot = this.slots[index]
    if (!slot?.profile) return null
    const copy = JSON.parse(JSON.stringify(slot.profile))
    copy.id = copy.id || uid()
    copy.lastActive = Date.now()
    const idx = this.state.profiles.findIndex(p => p.id === copy.id)
    if (idx >= 0) this.state.profiles[idx] = copy
    else this.state.profiles.push(copy)
    this.state.currentProfileId = copy.id
    this.persist()
    return copy
  }

  clearSlot(index) {
    this.slots[index] = null
    this.persist()
  }

  hasContinue() {
    return this.profiles().length > 0
  }

  exportProfile() {
    return JSON.stringify(this.profile(), null, 2)
  }
}

export function formatMoney(n) {
  return '$' + Math.round(n || 0).toLocaleString('en-US')
}

export function formatTime(sec) {
  if (sec == null || !Number.isFinite(sec)) return '--:--.--'
  const m = Math.floor(sec / 60)
  const s = Math.floor(sec % 60)
  const cs = Math.floor((sec % 1) * 100)
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`
}

// Procedural dark-classical score + arcade SFX. No external audio assets.
const NOTE = m => 440 * Math.pow(2, (m - 69) / 12)

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.music = null
    this.sfx = null
    this.vol = { master: 0.8, music: 0.7, sfx: 0.85 }
    this.scene = null
    this.timer = null
    this.nextTime = 0
    this.step = 0
    this.engine = null
    this.started = false
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {})
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.music = this.ctx.createGain()
    this.sfx = this.ctx.createGain()
    this.music.connect(this.master)
    this.sfx.connect(this.master)
    this.master.connect(this.ctx.destination)
    this.applyVolumes()
    this.started = true
  }

  applyVolumes() {
    if (!this.ctx) return
    const now = this.ctx.currentTime
    this.master.gain.setTargetAtTime(this.vol.master, now, 0.05)
    this.music.gain.setTargetAtTime(this.vol.music * 0.7, now, 0.05)
    this.sfx.gain.setTargetAtTime(this.vol.sfx, now, 0.05)
  }

  setVolumes({ master, music, sfx } = {}) {
    if (master != null) this.vol.master = master
    if (music != null) this.vol.music = music
    if (sfx != null) this.vol.sfx = sfx
    this.applyVolumes()
  }

  setScene(scene) {
    this.ensure()
    if (!this.ctx) return
    if (this.scene === scene) return
    this.scene = scene
    this.step = 0
    this.nextTime = this.ctx.currentTime + 0.08
    if (this.timer) clearInterval(this.timer)
    if (!scene) return
    this.timer = setInterval(() => this.scheduler(), 25)
  }

  scheduler() {
    if (!this.ctx || !this.scene) return
    const bpm = this.scene === 'race' ? 136 : this.scene === 'results' ? 92 : 74
    const stepDur = 60 / bpm / 4
    while (this.nextTime < this.ctx.currentTime + 0.2) {
      this.playStep(this.step, this.nextTime, stepDur)
      this.step = (this.step + 1) % 64
      this.nextTime += stepDur
    }
  }

  playStep(step, t, sd) {
    const menu = this.scene === 'menu' || this.scene === 'results'
    const bar = Math.floor(step / 16)
    const s = step % 16
    const chordsMenu = [
      [50, 53, 57, 62], // Dm
      [46, 50, 53, 58], // Bb
      [43, 50, 55, 58], // Gm
      [45, 49, 52, 57] // A
    ]
    const chordsRace = [
      [38, 50, 53, 57],
      [36, 48, 52, 55],
      [34, 46, 50, 53],
      [33, 45, 49, 52]
    ]
    const chords = menu ? chordsMenu : chordsRace
    const chord = chords[bar % 4]

    if (menu) {
      // Low organ drone on bar start
      if (s === 0) {
        chord.slice(0, 3).forEach((n, i) => this.tone(NOTE(n), t, sd * 15, 0.055, 'sawtooth', { filter: 520 + i * 90, attack: 0.9, release: 1.8, detune: i * 3 }))
        this.tone(NOTE(chord[0] - 12), t, sd * 16, 0.07, 'sine', { attack: 0.5, release: 2 })
      }
      // Cello ostinato
      if (s % 2 === 0) {
        const pattern = [0, 0, 7, 0, 10, 7, 0, 5]
        const n = chord[0] - 12 + pattern[(s / 2) % 8]
        this.tone(NOTE(n), t, sd * 1.7, 0.085, 'sawtooth', { filter: 340, attack: 0.02, release: 0.25 })
      }
      // Timpani
      if (s === 0 || s === 6 || s === 10) this.kick(t, s === 0 ? 0.2 : 0.12, menu ? 82 : 100)
      // Bell / harpsichord dread
      if (s === 8 && bar % 2 === 0) this.tone(NOTE(chord[2] + 24), t, 1.8, 0.035, 'triangle', { attack: 0.005, release: 1.6 })
      if (s === 12 && bar === 3) this.tone(NOTE(chord[1] + 12), t, 1.2, 0.04, 'sawtooth', { filter: 1800, attack: 0.01, release: 1 })
    } else {
      // Race: driving strings, brass, industrial percussion
      if (s === 0) {
        this.tone(NOTE(chord[0] - 12), t, sd * 14, 0.1, 'sawtooth', { filter: 260, attack: 0.1, release: 0.6 })
      }
      const bassPattern = [0, 0, 12, 0, 7, 0, 10, 12]
      if (s % 2 === 0) {
        const n = chord[0] + bassPattern[(s / 2) % 8]
        this.tone(NOTE(n - 12), t, sd * 1.45, 0.105, 'square', { filter: 300, attack: 0.005, release: 0.16 })
      }
      // string stabs
      if (s === 0 || s === 6) {
        chord.slice(1).forEach(n => this.tone(NOTE(n + 12), t, sd * 2.2, 0.034, 'sawtooth', { filter: 2100, attack: 0.01, release: 0.25, detune: 4 }))
      }
      // brass alarm
      if (s === 12 && bar % 2 === 1) {
        this.tone(NOTE(chord[2] + 12), t, sd * 2, 0.045, 'square', { filter: 1200, attack: 0.01, release: 0.4 })
        this.tone(NOTE(chord[3] + 12), t + sd * 0.5, sd * 1.6, 0.04, 'square', { filter: 1200, attack: 0.01, release: 0.4 })
      }
      if (s === 0 || s === 4 || s === 8 || s === 12) this.kick(t, s === 0 ? 0.22 : 0.15, 96)
      if (s === 2 || s === 10) this.snare(t, 0.1)
      if (s % 2 === 1) this.hat(t, 0.025)
    }
  }

  tone(freq, t, dur, gain, type = 'sine', opts = {}) {
    if (!this.ctx) return
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    const f = this.ctx.createBiquadFilter()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (opts.detune) o.detune.setValueAtTime(opts.detune, t)
    f.type = 'lowpass'
    f.frequency.setValueAtTime(opts.filter || 1600, t)
    f.Q.value = opts.q || 0.7
    const a = opts.attack ?? 0.02
    const r = opts.release ?? 0.3
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + a)
    g.gain.setTargetAtTime(0.0001, t + Math.max(a, dur - r), Math.max(0.02, r / 3))
    o.connect(f); f.connect(g); g.connect(this.music)
    o.start(t)
    o.stop(t + dur + 0.1)
  }

  kick(t, gain = 0.2, startFreq = 100) {
    if (!this.ctx) return
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = 'sine'
    o.frequency.setValueAtTime(startFreq, t)
    o.frequency.exponentialRampToValueAtTime(32, t + 0.22)
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.32)
    o.connect(g); g.connect(this.music)
    o.start(t); o.stop(t + 0.34)
  }

  snare(t, gain = 0.1) {
    if (!this.ctx) return
    const len = 0.16
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length)
    const src = this.ctx.createBufferSource()
    src.buffer = buf
    const f = this.ctx.createBiquadFilter()
    f.type = 'bandpass'; f.frequency.value = 1700; f.Q.value = 0.8
    const g = this.ctx.createGain(); g.gain.value = gain
    src.connect(f); f.connect(g); g.connect(this.music)
    src.start(t)
  }

  hat(t, gain = 0.03) {
    if (!this.ctx) return
    const len = 0.045
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 2)
    const src = this.ctx.createBufferSource(); src.buffer = buf
    const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 6500
    const g = this.ctx.createGain(); g.gain.value = gain
    src.connect(f); f.connect(g); g.connect(this.music)
    src.start(t)
  }

  sfx(name, extra = {}) {
    this.ensure()
    if (!this.ctx || this.vol.sfx <= 0.001) return
    const t = this.ctx.currentTime
    const g = this.sfx
    if (name === 'click') {
      this.blip(t, 420, 0.06, 0.08, 'square')
    } else if (name === 'back') {
      this.blip(t, 240, 0.09, 0.07, 'square')
    } else if (name === 'count') {
      this.blip(t, 320, 0.18, 0.16, 'square', 600)
    } else if (name === 'go') {
      this.blip(t, 620, 0.45, 0.2, 'sawtooth', 1240)
      this.kickSfx(t, 0.2, 90)
    } else if (name === 'boost') {
      this.whoosh(t, 0.45, 0.16, 280, 1800)
    } else if (name === 'hit') {
      this.noiseSfx(t, 0.12, 0.16, 420)
      this.blip(t, 90, 0.16, 0.1, 'square', 40)
    } else if (name === 'scrape') {
      this.noiseSfx(t, 0.08, 0.06, 2600)
    } else if (name === 'lightning') {
      this.noiseSfx(t, 0.7, 0.3, 900)
      this.kickSfx(t, 0.15, 70)
    } else if (name === 'win') {
      [58, 62, 65, 70, 74].forEach((n, i) => this.musicBlip(t + i * 0.09, NOTE(n), 0.5, 0.09, 'sawtooth'))
    } else if (name === 'lose') {
      [58, 55, 51, 46].forEach((n, i) => this.musicBlip(t + i * 0.14, NOTE(n), 0.7, 0.09, 'sawtooth'))
    } else if (name === 'reward') {
      [70, 74, 77, 82].forEach((n, i) => this.blip(t + i * 0.07, NOTE(n), 0.35, 0.08, 'triangle'))
    } else if (name === 'siren') {
      this.siren(t)
    } else if (name === 'thunder') {
      this.noiseSfx(t, 1.2, 0.22, 320)
    } else if (name === 'ui_open') {
      this.blip(t, 180, 0.2, 0.08, 'sawtooth', 380)
    }
  }

  blip(t, freq, dur, gain, type = 'square', targetFreq = null) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain()
    o.type = type; o.frequency.setValueAtTime(freq, t)
    if (targetFreq) o.frequency.exponentialRampToValueAtTime(targetFreq, t + dur)
    g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g); g.connect(this.sfx); o.start(t); o.stop(t + dur + 0.02)
  }

  blip2(t, f1, f2, dur, gain, type = 'square') {
    this.blip(t, f1, dur, gain, type, f2)
  }

  kickSfx(t, gain, freq) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain()
    o.type = 'sine'; o.frequency.setValueAtTime(freq, t); o.frequency.exponentialRampToValueAtTime(30, t + 0.28)
    g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
    o.connect(g); g.connect(this.sfx); o.start(t); o.stop(t + 0.32)
  }

  noiseSfx(t, dur, gain, freq) {
    const len = dur
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 1.4)
    const src = this.ctx.createBufferSource(); src.buffer = buf
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = freq
    const g = this.ctx.createGain(); g.gain.value = gain
    src.connect(f); f.connect(g); g.connect(this.sfx); src.start(t)
  }

  whoosh(t, dur, gain, f1, f2) {
    const len = dur
    const buf = this.ctx.createBuffer(1, this.ctx.sampleRate * len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.sin((i / d.length) * Math.PI)
    const src = this.ctx.createBufferSource(); src.buffer = buf
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.Q.value = 1.2
    f.frequency.setValueAtTime(f1, t); f.frequency.exponentialRampToValueAtTime(f2, t + dur)
    const g = this.ctx.createGain(); g.gain.value = gain
    src.connect(f); f.connect(g); g.connect(this.sfx); src.start(t)
  }

  siren(t) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain()
    o.type = 'sawtooth'; o.frequency.setValueAtTime(580, t)
    o.frequency.linearRampToValueAtTime(940, t + 0.35)
    o.frequency.linearRampToValueAtTime(580, t + 0.7)
    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.08, t + 0.05)
    g.gain.linearRampToValueAtTime(0.0001, t + 0.75)
    o.connect(g); g.connect(this.sfx); o.start(t); o.stop(t + 0.8)
  }

  musicBlip(t, freq, dur, gain, type) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain()
    o.type = type; o.frequency.setValueAtTime(freq, t)
    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(gain, t + 0.02)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g); g.connect(this.music); o.start(t); o.stop(t + dur + 0.02)
  }

  startEngine() {
    this.ensure()
    if (!this.ctx || this.engine) return
    const o1 = this.ctx.createOscillator()
    const o2 = this.ctx.createOscillator()
    const f = this.ctx.createBiquadFilter()
    const g = this.ctx.createGain()
    o1.type = 'sawtooth'; o2.type = 'square'
    o1.frequency.value = 45; o2.frequency.value = 90
    f.type = 'lowpass'; f.frequency.value = 420; f.Q.value = 1.4
    g.gain.value = 0.0001
    o1.connect(f); o2.connect(f); f.connect(g); g.connect(this.sfx)
    o1.start(); o2.start()
    g.gain.setTargetAtTime(0.045, this.ctx.currentTime, 0.5)
    this.engine = { o1, o2, f, g }
  }

  updateEngine(speed, throttle = 0, boost = false) {
    if (!this.engine || !this.ctx) return
    const t = this.ctx.currentTime
    const v = Math.min(1, speed / 60)
    this.engine.o1.frequency.setTargetAtTime(42 + v * 150 + (boost ? 60 : 0), t, 0.06)
    this.engine.o2.frequency.setTargetAtTime(84 + v * 290 + (boost ? 110 : 0), t, 0.06)
    this.engine.f.frequency.setTargetAtTime(300 + v * 1200 + throttle * 240, t, 0.1)
    this.engine.g.gain.setTargetAtTime(0.028 + v * 0.035 + (boost ? 0.02 : 0), t, 0.08)
  }

  stopEngine() {
    if (!this.engine || !this.ctx) return
    const e = this.engine
    e.g.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.15)
    setTimeout(() => {
      try { e.o1.stop(); e.o2.stop() } catch {}
    }, 500)
    this.engine = null
  }

  stopAll() {
    if (this.timer) clearInterval(this.timer)
    this.timer = null
    this.scene = null
    this.stopEngine()
  }
}

export const audio = new AudioEngine()

import { EYE_COLORS, HAIR_COLORS, ORIGINS } from './data.js'

function shade(hex, amt) {
  const h = hex.replace('#', '')
  const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16)
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255
  r = Math.max(0, Math.min(255, r + amt))
  g = Math.max(0, Math.min(255, g + amt))
  b = Math.max(0, Math.min(255, b + amt))
  return `rgb(${r},${g},${b})`
}

function seed(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) }
  return () => {
    h += 0x6D2B79F5
    let t = h
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function colorOf(list, id, fallback) {
  return list.find(x => x.id === id)?.value || fallback
}

function eyeColorOf(list, id) {
  return list.find(x => x.id === id) || EYE_COLORS[0]
}

export function mergedLooks(looks = {}) {
  const origin = looks.origin || 'human'
  const originDef = ORIGINS.find(o => o.id === origin) || ORIGINS[0]
  return {
    gender: 'female',
    face: 'sharp',
    hair: 'mohawk',
    hairColor: 'black',
    eyeColor: 'blue',
    eyeStyle: 'human',
    facialHair: 'none',
    scar: 'none',
    headgear: 'none',
    skin: originDef.skin,
    ...looks,
    origin
  }
}

export function drawPortrait(canvas, rawLooks = {}, opts = {}) {
  const looks = mergedLooks(rawLooks)
  const dpr = Math.min(2, window.devicePixelRatio || 1)
  const size = opts.size || 512
  canvas.width = size * dpr
  canvas.height = size * dpr
  const ctx = canvas.getContext('2d')
  ctx.scale((size * dpr) / 512, (size * dpr) / 512)
  const rnd = seed((looks.name || '') + JSON.stringify(looks))
  const skin = looks.skin || '#b9866b'
  const skinDark = shade(skin, -52)
  const skinLight = shade(skin, 40)
  const hairCol = colorOf(HAIR_COLORS, looks.hairColor, looks.hairHex || '#151316')
  const eyeDef = eyeColorOf(EYE_COLORS, looks.eyeColor)
  const eyeCol = eyeDef.value
  const eyeGlow = eyeDef.glow || eyeCol
  const cx = 256
  const cy = 238
  const w = looks.face === 'broad' ? 66 : looks.face === 'gaunt' ? 52 : looks.face === 'round' ? 61 : 58
  const female = looks.gender === 'female'
  const origin = looks.origin || 'human'
  const boss = opts.boss

  // ---- backdrop -----------------------------------------------------------
  const bg = ctx.createRadialGradient(cx, cy - 10, 20, cx, cy, 360)
  bg.addColorStop(0, opts.bg || '#361c18')
  bg.addColorStop(0.55, '#160f10')
  bg.addColorStop(1, '#070708')
  ctx.fillStyle = bg
  ctx.fillRect(0, 0, 512, 512)
  ctx.save()
  ctx.globalAlpha = 0.14
  ctx.strokeStyle = boss ? '#c1121f' : '#d8a44a'
  for (let i = 0; i < 9; i++) {
    ctx.lineWidth = 1 + rnd() * 2
    ctx.beginPath()
    let x = rnd() * 512, y = 0
    ctx.moveTo(x, y)
    for (let j = 0; j < 5; j++) { x += (rnd() - 0.5) * 70; y += 90 + rnd() * 30; ctx.lineTo(x, y) }
    ctx.stroke()
  }
  ctx.restore()
  // hazard arc
  ctx.save()
  ctx.translate(cx, cy)
  ctx.strokeStyle = 'rgba(205,164,74,0.18)'
  ctx.lineWidth = 2
  ctx.beginPath(); ctx.arc(0, 0, 218, 0.15, Math.PI * 1.85); ctx.stroke()
  ctx.strokeStyle = 'rgba(160,20,26,0.25)'
  ctx.beginPath(); ctx.arc(0, 0, 230, Math.PI * 0.2, Math.PI * 1.55); ctx.stroke()
  ctx.restore()

  // ---- body / shoulders ---------------------------------------------------
  ctx.save()
  const jacket = looks.jacket || (origin === 'ghost' ? '#313943' : boss ? '#201417' : '#232327')
  const jacketHi = shade(jacket, 28)
  const bodyGrad = ctx.createLinearGradient(0, 370, 0, 512)
  bodyGrad.addColorStop(0, jacketHi)
  bodyGrad.addColorStop(1, '#0b0b0c')
  ctx.fillStyle = bodyGrad
  ctx.beginPath()
  ctx.moveTo(52, 512)
  ctx.bezierCurveTo(58, 415, 122, 380, 190, 366)
  ctx.lineTo(322, 366)
  ctx.bezierCurveTo(390, 380, 454, 415, 460, 512)
  ctx.closePath()
  ctx.fill()
  // collar
  ctx.fillStyle = shade(jacket, 42)
  ctx.beginPath()
  ctx.moveTo(186, 366); ctx.lineTo(256, 454); ctx.lineTo(326, 366)
  ctx.lineTo(300, 354); ctx.lineTo(256, 414); ctx.lineTo(212, 354)
  ctx.closePath(); ctx.fill()
  // straps
  ctx.strokeStyle = 'rgba(0,0,0,0.55)'; ctx.lineWidth = 12
  ctx.beginPath(); ctx.moveTo(150, 402); ctx.lineTo(224, 512); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(362, 402); ctx.lineTo(288, 512); ctx.stroke()
  ctx.strokeStyle = 'rgba(180,38,34,0.5)'; ctx.lineWidth = 3
  ctx.beginPath(); ctx.moveTo(154, 406); ctx.lineTo(228, 512); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(358, 406); ctx.lineTo(284, 512); ctx.stroke()
  // shoulder studs
  ctx.fillStyle = '#b8a57b'
  for (let i = 0; i < 5; i++) {
    ctx.beginPath(); ctx.arc(118 + i * 16, 422 + i * 15, 2.6, 0, 7); ctx.fill()
    ctx.beginPath(); ctx.arc(394 - i * 16, 422 + i * 15, 2.6, 0, 7); ctx.fill()
  }
  // stitched patch
  ctx.fillStyle = 'rgba(0,0,0,0.42)'
  ctx.fillRect(310, 452, 74, 34)
  ctx.strokeStyle = 'rgba(190,160,100,0.5)'; ctx.lineWidth = 1.5; ctx.setLineDash([4, 4])
  ctx.strokeRect(314, 456, 66, 26); ctx.setLineDash([])
  ctx.fillStyle = 'rgba(190,160,100,0.65)'; ctx.font = 'bold 14px monospace'; ctx.textAlign = 'center'
  ctx.fillText('HELL', 347, 474)
  ctx.restore()

  // ---- neck ---------------------------------------------------------------
  ctx.fillStyle = skinDark
  ctx.beginPath()
  ctx.moveTo(cx - 28, 320); ctx.lineTo(cx + 28, 320)
  ctx.lineTo(cx + 34, 384); ctx.lineTo(cx - 34, 384); ctx.closePath(); ctx.fill()
  ctx.fillStyle = 'rgba(0,0,0,0.35)'
  ctx.beginPath(); ctx.ellipse(cx, 326, 31, 12, 0, 0, 7); ctx.fill()

  // ---- hair back ----------------------------------------------------------
  if (looks.hair === 'long' || looks.hair === 'braids' || looks.hair === 'wild' || looks.hair === 'ponytail') {
    ctx.fillStyle = hairCol
    if (looks.hair === 'ponytail') {
      ctx.beginPath()
      ctx.ellipse(cx + 64, 230, 26, 74, -0.3, 0, 7)
      ctx.fill()
      ctx.beginPath(); ctx.ellipse(cx + 84, 304, 20, 52, -0.15, 0, 7); ctx.fill()
    } else {
      ctx.beginPath()
      ctx.moveTo(cx - w - 12, 170)
      ctx.bezierCurveTo(cx - w - 48, 270, cx - w - 24, 370, cx - w + 8, 400)
      ctx.lineTo(cx + w - 2, 400)
      ctx.bezierCurveTo(cx + w + 34, 350, cx + w + 38, 240, cx + w + 8, 166)
      ctx.closePath(); ctx.fill()
      if (looks.hair === 'braids') {
        ctx.strokeStyle = shade(hairCol, 25); ctx.lineWidth = 10
        for (let i = 0; i < 4; i++) {
          ctx.beginPath(); ctx.moveTo(cx - w + 8 + i * 16, 300); ctx.quadraticCurveTo(cx - w + 20 + i * 16, 360, cx - w + 8 + i * 16, 420); ctx.stroke()
          ctx.beginPath(); ctx.moveTo(cx + w - 8 - i * 16, 300); ctx.quadraticCurveTo(cx + w - 20 - i * 16, 360, cx + w - 8 - i * 16, 420); ctx.stroke()
        }
      }
    }
  }

  // ---- head ---------------------------------------------------------------
  const headPath = () => {
    ctx.beginPath()
    ctx.moveTo(cx - w, cy - 32)
    ctx.bezierCurveTo(cx - w - 2, cy - 122, cx + w + 2, cy - 122, cx + w, cy - 32)
    ctx.bezierCurveTo(cx + w * 0.98, cy + 26, cx + w * 0.66, cy + 84, cx + (female ? 20 : 26), cy + 108)
    ctx.quadraticCurveTo(cx, cy + 120, cx - (female ? 20 : 26), cy + 108)
    ctx.bezierCurveTo(cx - w * 0.66, cy + 84, cx - w * 0.98, cy + 26, cx - w, cy - 32)
    ctx.closePath()
  }
  // ears behind
  ctx.fillStyle = skinDark
  ctx.beginPath(); ctx.ellipse(cx - w + 2, cy - 5, 13, 22, 0.2, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.ellipse(cx + w - 2, cy - 5, 13, 22, -0.2, 0, 7); ctx.fill()
  const skinGrad = ctx.createLinearGradient(cx - w, cy - 100, cx + w, cy + 110)
  skinGrad.addColorStop(0, skinLight)
  skinGrad.addColorStop(0.45, skin)
  skinGrad.addColorStop(1, skinDark)
  ctx.fillStyle = skinGrad
  headPath(); ctx.fill()

  // facial structure shadow
  ctx.save(); headPath(); ctx.clip()
  ctx.fillStyle = 'rgba(0,0,0,0.16)'
  ctx.beginPath(); ctx.ellipse(cx - w * 0.72, cy + 10, 18, 70, 0.08, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.ellipse(cx + w * 0.72, cy + 10, 18, 70, -0.08, 0, 7); ctx.fill()
  // cheek highlights
  ctx.fillStyle = 'rgba(255,255,255,0.1)'
  ctx.beginPath(); ctx.ellipse(cx - 31, cy + 32, 17, 9, -0.3, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.ellipse(cx + 31, cy + 32, 17, 9, 0.3, 0, 7); ctx.fill()
  // grime
  for (let i = 0; i < 26; i++) {
    ctx.fillStyle = `rgba(${30 + rnd() * 40},${22 + rnd() * 30},${18 + rnd() * 20},${0.04 + rnd() * 0.1})`
    ctx.beginPath(); ctx.arc(cx - w + rnd() * w * 2, cy - 90 + rnd() * 195, 1 + rnd() * 6, 0, 7); ctx.fill()
  }
  ctx.restore()

  // ---- eye sockets --------------------------------------------------------
  const eyeY = cy - 10
  const ex = w * 0.42
  const eyeW = w * 0.28
  const eyeH = eyeStyleHeight(looks.eyeStyle, female)
  const drawEye = (side) => {
    const x = cx + side * ex
    if (looks.eyeStyle === 'cyber') {
      ctx.save()
      ctx.fillStyle = 'rgba(15,10,12,0.82)'
      ctx.beginPath()
      ctx.moveTo(x - 23, eyeY - 12); ctx.lineTo(x + 23, eyeY - 12)
      ctx.lineTo(x + 20, eyeY + 11); ctx.lineTo(x - 20, eyeY + 11); ctx.closePath(); ctx.fill()
      ctx.strokeStyle = 'rgba(160,140,110,0.5)'; ctx.lineWidth = 1.5; ctx.stroke()
      ctx.shadowBlur = 16; ctx.shadowColor = eyeGlow
      ctx.fillStyle = eyeGlow
      ctx.beginPath(); ctx.roundRect(x - 15, eyeY - 2.5, 30, 5, 3); ctx.fill()
      ctx.restore()
      return
    }
    if (looks.eyeStyle === 'hollow') {
      ctx.save()
      const g = ctx.createRadialGradient(x, eyeY, 1, x, eyeY, 22)
      g.addColorStop(0, eyeCol); g.addColorStop(0.25, eyeGlow); g.addColorStop(0.4, 'rgba(8,6,7,0.9)'); g.addColorStop(1, '#0a0708')
      ctx.fillStyle = g
      ctx.beginPath(); ctx.ellipse(x, eyeY, 20, 17, 0, 0, 7); ctx.fill()
      ctx.fillStyle = '#050405'
      ctx.beginPath(); ctx.ellipse(x, eyeY, 7, 11, 0, 0, 7); ctx.fill()
      ctx.shadowBlur = 15; ctx.shadowColor = eyeGlow
      ctx.fillStyle = eyeCol
      ctx.beginPath(); ctx.arc(x, eyeY, 3.4, 0, 7); ctx.fill()
      ctx.restore()
      return
    }
    // sclera
    ctx.save()
    ctx.fillStyle = origin === 'ghost' ? 'rgba(220,230,232,0.75)' : '#ded7c9'
    ctx.beginPath(); ctx.ellipse(x, eyeY, eyeW, eyeH, 0, 0, 7); ctx.fill()
    ctx.strokeStyle = 'rgba(25,15,14,0.6)'; ctx.lineWidth = 1.6
    ctx.beginPath(); ctx.ellipse(x, eyeY, eyeW, eyeH, 0, 0, 7); ctx.stroke()
    // iris
    ctx.shadowBlur = eyeDef.glow ? 13 : 0; ctx.shadowColor = eyeGlow
    const ig = ctx.createRadialGradient(x, eyeY, 1, x, eyeY, eyeW * 0.7)
    ig.addColorStop(0, eyeGlow); ig.addColorStop(0.55, eyeCol); ig.addColorStop(1, shade(eyeCol, -55))
    ctx.fillStyle = ig
    ctx.beginPath(); ctx.arc(x, eyeY, eyeW * 0.68, 0, 7); ctx.fill()
    ctx.shadowBlur = 0
    ctx.fillStyle = '#070607'
    ctx.beginPath(); ctx.ellipse(x, eyeY, eyeW * 0.22, eyeH * 0.62, 0, 0, 7); ctx.fill()
    ctx.fillStyle = 'rgba(255,255,255,0.85)'
    ctx.beginPath(); ctx.arc(x - 3, eyeY - 3, 2.1, 0, 7); ctx.fill()
    // tired lines
    ctx.strokeStyle = 'rgba(40,25,25,0.35)'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.moveTo(x - eyeW, eyeY + eyeH + 2); ctx.quadraticCurveTo(x, eyeY + eyeH + 7, x + eyeW, eyeY + eyeH + 2); ctx.stroke()
    ctx.restore()
  }
  drawEye(-1); drawEye(1)

  // brows
  ctx.strokeStyle = shade(hairCol, 18)
  ctx.lineWidth = female ? 4 : 6
  ctx.lineCap = 'round'
  ctx.beginPath(); ctx.moveTo(cx - ex - 15, eyeY - 18); ctx.quadraticCurveTo(cx - ex, eyeY - 25, cx - ex + 14, eyeY - 17); ctx.stroke()
  ctx.beginPath(); ctx.moveTo(cx + ex - 14, eyeY - 17); ctx.quadraticCurveTo(cx + ex, eyeY - 25, cx + ex + 15, eyeY - 18); ctx.stroke()
  if (looks.browScar || looks.scar === 'eye') {
    ctx.strokeStyle = 'rgba(220,170,150,0.65)'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(cx + ex - 10, eyeY - 40); ctx.lineTo(cx + ex + 16, eyeY + 7); ctx.stroke()
  }

  // nose
  ctx.strokeStyle = 'rgba(55,30,26,0.45)'; ctx.lineWidth = female ? 3 : 4
  ctx.beginPath(); ctx.moveTo(cx - 2, eyeY + 8); ctx.quadraticCurveTo(cx - 8, cy + 35, cx - 13, cy + 39); ctx.stroke()
  ctx.strokeStyle = 'rgba(0,0,0,0.25)'; ctx.lineWidth = 2
  ctx.beginPath(); ctx.moveTo(cx - 14, cy + 41); ctx.quadraticCurveTo(cx, cy + 47, cx + 15, cy + 40); ctx.stroke()
  ctx.fillStyle = 'rgba(0,0,0,0.16)'
  ctx.beginPath(); ctx.ellipse(cx - 13, cy + 40, 4, 2.4, 0, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.ellipse(cx + 13, cy + 40, 4, 2.4, 0, 0, 7); ctx.fill()

  // mouth
  const my = cy + 70
  ctx.strokeStyle = looks.joker ? '#4b0b1f' : 'rgba(65,26,28,0.9)'
  ctx.lineWidth = female ? 5 : 4
  ctx.beginPath()
  if (looks.joker) {
    ctx.moveTo(cx - 38, my - 2); ctx.quadraticCurveTo(cx, my + 24, cx + 38, my - 2)
    ctx.stroke()
    ctx.strokeStyle = 'rgba(180,20,40,0.85)'; ctx.lineWidth = 2.5
    ctx.beginPath(); ctx.moveTo(cx - 43, my - 8); ctx.quadraticCurveTo(cx, my + 30, cx + 43, my - 8); ctx.stroke()
  } else {
    ctx.moveTo(cx - 20, my); ctx.quadraticCurveTo(cx, my + (female ? 8 : 4), cx + 20, my)
    ctx.stroke()
  }
  // lower lip
  if (female) {
    ctx.fillStyle = 'rgba(120,50,50,0.4)'
    ctx.beginPath(); ctx.ellipse(cx, my + 7, 16, 4, 0, 0, 7); ctx.fill()
  }
  if (looks.fangs) {
    ctx.fillStyle = '#e8e2d2'
    ctx.beginPath(); ctx.moveTo(cx - 19, my + 2); ctx.lineTo(cx - 13, my + 13); ctx.lineTo(cx - 8, my + 2); ctx.fill()
    ctx.beginPath(); ctx.moveTo(cx + 19, my + 2); ctx.lineTo(cx + 13, my + 13); ctx.lineTo(cx + 8, my + 2); ctx.fill()
  }

  // facial hair
  const fh = looks.facialHair
  if (fh && fh !== 'none') {
    ctx.fillStyle = hairCol
    if (fh === 'stubble') {
      ctx.save(); ctx.globalAlpha = 0.25
      ctx.beginPath(); ctx.ellipse(cx, cy + 66, 44, 42, 0, 0, Math.PI); ctx.fill(); ctx.restore()
    } else if (fh === 'mustache') {
      ctx.beginPath(); ctx.moveTo(cx - 24, my - 7); ctx.quadraticCurveTo(cx, my - 16, cx + 24, my - 7); ctx.quadraticCurveTo(cx, my + 3, cx - 24, my - 7); ctx.fill()
    } else if (fh === 'goatee') {
      ctx.beginPath(); ctx.ellipse(cx, my + 18, 14, 20, 0, 0, 7); ctx.fill()
      ctx.beginPath(); ctx.moveTo(cx - 20, my - 8); ctx.quadraticCurveTo(cx, my - 15, cx + 20, my - 8); ctx.quadraticCurveTo(cx, my, cx - 20, my - 8); ctx.fill()
    } else {
      ctx.beginPath()
      ctx.moveTo(cx - 43, cy + 30)
      ctx.bezierCurveTo(cx - 50, cy + 108, cx - 20, cy + 128, cx, cy + 125)
      ctx.bezierCurveTo(cx + 20, cy + 128, cx + 50, cy + 108, cx + 43, cy + 30)
      ctx.quadraticCurveTo(cx + 30, cy + 70, cx, cy + 74)
      ctx.quadraticCurveTo(cx - 30, cy + 70, cx - 43, cy + 30)
      ctx.fill()
      if (fh === 'braided') {
        ctx.strokeStyle = shade(hairCol, 35); ctx.lineWidth = 2
        for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.moveTo(cx - 18 + i * 18, cy + 95); ctx.lineTo(cx - 14 + i * 18, cy + 132); ctx.stroke() }
      }
    }
  }

  // scars
  const scar = looks.scar
  if (scar === 'eye') {
    ctx.strokeStyle = 'rgba(210,155,140,0.8)'; ctx.lineWidth = 2.5
    ctx.beginPath(); ctx.moveTo(cx + ex - 6, eyeY - 44); ctx.lineTo(cx + ex + 14, eyeY + 16); ctx.stroke()
    ctx.strokeStyle = 'rgba(110,35,35,0.55)'; ctx.lineWidth = 1
    ctx.beginPath(); ctx.moveTo(cx + ex - 4, eyeY - 20); ctx.lineTo(cx + ex + 9, eyeY - 16); ctx.stroke()
  } else if (scar === 'cheek') {
    ctx.strokeStyle = 'rgba(205,150,135,0.75)'; ctx.lineWidth = 2.2
    ctx.beginPath(); ctx.moveTo(cx - w + 15, cy + 12); ctx.lineTo(cx - w + 34, cy + 55); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx - w + 25, cy + 34); ctx.lineTo(cx - w + 42, cy + 30); ctx.stroke()
  } else if (scar === 'x') {
    ctx.strokeStyle = 'rgba(200,145,130,0.8)'; ctx.lineWidth = 2.4
    ctx.beginPath(); ctx.moveTo(cx - 50, cy + 18); ctx.lineTo(cx - 24, cy + 50); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx - 24, cy + 18); ctx.lineTo(cx - 50, cy + 50); ctx.stroke()
  } else if (scar === 'burn') {
    ctx.save(); ctx.globalAlpha = 0.45
    const g = ctx.createRadialGradient(cx + 38, cy + 38, 2, cx + 38, cy + 38, 30)
    g.addColorStop(0, '#6e2a25'); g.addColorStop(1, 'rgba(60,20,20,0)')
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx + 38, cy + 38, 30, 0, 7); ctx.fill()
    ctx.restore()
  }

  // ---- hair front ---------------------------------------------------------
  ctx.fillStyle = hairCol
  if (looks.hair === 'mohawk') {
    ctx.beginPath()
    ctx.moveTo(cx - 12, cy - 90)
    ctx.bezierCurveTo(cx - 20, cy - 170, cx + 20, cy - 174, cx + 12, cy - 90)
    ctx.lineTo(cx + 42, cy - 82)
    ctx.bezierCurveTo(cx + 34, cy - 140, cx - 30, cy - 144, cx - 42, cy - 82)
    ctx.closePath(); ctx.fill()
    ctx.fillStyle = shade(hairCol, 30)
    for (let i = 0; i < 5; i++) { ctx.beginPath(); ctx.arc(cx - 18 + i * 9, cy - 125 + (i % 2) * 6, 3, 0, 7); ctx.fill() }
  } else if (looks.hair === 'bald' || looks.hair === 'buzz') {
    if (looks.hair === 'buzz') {
      ctx.save(); ctx.globalAlpha = 0.5
      ctx.beginPath(); ctx.ellipse(cx, cy - 46, w - 3, 50, 0, Math.PI, Math.PI * 2); ctx.fill()
      ctx.restore()
    }
    // forehead scars
    if (!scar || scar === 'none') {
      ctx.strokeStyle = 'rgba(190,140,125,0.4)'; ctx.lineWidth = 1.5
      ctx.beginPath(); ctx.moveTo(cx - 16, cy - 70); ctx.lineTo(cx + 4, cy - 52); ctx.stroke()
    }
  } else if (looks.hair === 'hood') {
    ctx.fillStyle = '#1c1c20'
    ctx.beginPath()
    ctx.moveTo(cx - w - 24, cy + 40)
    ctx.bezierCurveTo(cx - w - 34, cy - 150, cx + w + 34, cy - 150, cx + w + 24, cy + 40)
    ctx.bezierCurveTo(cx + w - 4, cy - 70, cx - w + 4, cy - 70, cx - w - 24, cy + 40)
    ctx.fill()
  } else {
    // swept fringe / long / wild / braids / ponytail
    ctx.beginPath()
    ctx.moveTo(cx - w - 2, cy - 26)
    ctx.bezierCurveTo(cx - w - 8, cy - 112, cx + w + 8, cy - 120, cx + w + 2, cy - 26)
    ctx.lineTo(cx + w - 6, cy - 20)
    if (looks.hair === 'wild') {
      ctx.lineTo(cx + 32, cy - 74); ctx.lineTo(cx + 18, cy - 48); ctx.lineTo(cx - 4, cy - 82); ctx.lineTo(cx - 26, cy - 40)
    } else if (looks.hair === 'long') {
      ctx.lineTo(cx + 38, cy - 66); ctx.lineTo(cx + 8, cy - 42); ctx.lineTo(cx - 22, cy - 80); ctx.lineTo(cx - 52, cy - 30)
    } else {
      ctx.lineTo(cx + 42, cy - 60); ctx.lineTo(cx + 6, cy - 52); ctx.lineTo(cx - 30, cy - 84); ctx.lineTo(cx - 58, cy - 20)
    }
    ctx.lineTo(cx - w + 6, cy - 20)
    ctx.closePath(); ctx.fill()
    // hair shine
    ctx.strokeStyle = 'rgba(255,255,255,0.13)'; ctx.lineWidth = 6
    ctx.beginPath(); ctx.moveTo(cx - 38, cy - 94); ctx.quadraticCurveTo(cx - 6, cy - 116, cx + 30, cy - 82); ctx.stroke()
  }

  // ---- origin / headgear --------------------------------------------------
  if (origin === 'demon' || looks.headgear === 'horns') {
    ctx.fillStyle = '#2a1714'
    ctx.beginPath(); ctx.moveTo(cx - w + 4, cy - 78); ctx.bezierCurveTo(cx - w - 38, cy - 150, cx - w - 12, cy - 190, cx - w + 10, cy - 128); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(cx + w - 4, cy - 78); ctx.bezierCurveTo(cx + w + 38, cy - 150, cx + w + 12, cy - 190, cx + w - 10, cy - 128); ctx.closePath(); ctx.fill()
    ctx.strokeStyle = 'rgba(180,60,40,0.35)'; ctx.lineWidth = 2
    ctx.beginPath(); ctx.moveTo(cx - w - 8, cy - 120); ctx.quadraticCurveTo(cx - w - 20, cy - 150, cx - w - 2, cy - 166); ctx.stroke()
  }

  if (looks.ghost) {
    ctx.save(); ctx.globalCompositeOperation = 'screen'; ctx.globalAlpha = 0.12
    ctx.fillStyle = '#82d7e8'
    ctx.beginPath(); ctx.ellipse(cx, cy + 40, w + 20, 160, 0, 0, 7); ctx.fill(); ctx.restore()
  }

  if (looks.wool) {
    ctx.fillStyle = '#e6e0d0'
    for (let i = 0; i < 12; i++) {
      const a = -Math.PI + (i / 11) * Math.PI
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * (w + 2), cy - 40 + Math.sin(a) * 65, 25, 0, 7); ctx.fill()
    }
  }

  if (looks.headgear === 'anubis' || looks.anubis) {
    // golden jackal mask
    ctx.fillStyle = '#16110c'
    ctx.beginPath(); ctx.moveTo(cx - w - 2, cy - 120); ctx.lineTo(cx - w - 8, cy - 210); ctx.lineTo(cx - 22, cy - 250); ctx.lineTo(cx - 34, cy - 150); ctx.lineTo(cx - w - 2, cy - 120); ctx.fill()
    ctx.beginPath(); ctx.moveTo(cx + w + 2, cy - 120); ctx.lineTo(cx + w + 8, cy - 210); ctx.lineTo(cx + 22, cy - 250); ctx.lineTo(cx + 34, cy - 150); ctx.lineTo(cx + w + 2, cy - 120); ctx.fill()
    ctx.strokeStyle = '#d8ab3c'; ctx.lineWidth = 3
    ctx.beginPath(); ctx.moveTo(cx - w - 4, cy - 130); ctx.lineTo(cx - 24, cy - 238); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx + w + 4, cy - 130); ctx.lineTo(cx + 24, cy - 238); ctx.stroke()
    // gold eye of horus
    ctx.strokeStyle = '#e7b93f'; ctx.lineWidth = 4
    ctx.beginPath(); ctx.moveTo(cx - 72, cy - 20); ctx.lineTo(cx - 22, cy - 20); ctx.quadraticCurveTo(cx - 34, cy + 20, cx - 60, cy + 8); ctx.stroke()
    ctx.strokeStyle = '#b98c2b'; ctx.lineWidth = 3
    ctx.beginPath(); ctx.moveTo(cx + 22, cy - 18); ctx.lineTo(cx + 72, cy - 18); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx + 54, cy - 18); ctx.quadraticCurveTo(cx + 62, cy + 20, cx + 34, cy + 18); ctx.stroke()
    ctx.fillStyle = '#e7b93f'
    ctx.beginPath(); ctx.moveTo(cx - 6, cy + 56); ctx.lineTo(cx + 6, cy + 56); ctx.lineTo(cx, cy + 74); ctx.fill()
  }

  if (looks.headgear === 'ears' || looks.ears) {
    const earCol = looks.earColor || (looks.hair === 'white' ? '#e2ddd1' : '#b66a3b')
    ctx.fillStyle = earCol
    ctx.beginPath(); ctx.moveTo(cx - w + 2, cy - 92); ctx.lineTo(cx - w - 44, cy - 218); ctx.lineTo(cx - 20, cy - 118); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(cx + w - 2, cy - 92); ctx.lineTo(cx + w + 44, cy - 218); ctx.lineTo(cx + 20, cy - 118); ctx.closePath(); ctx.fill()
    ctx.fillStyle = looks.furInner || '#6f4438'
    ctx.beginPath(); ctx.moveTo(cx - w + 4, cy - 108); ctx.lineTo(cx - w - 30, cy - 194); ctx.lineTo(cx - 26, cy - 126); ctx.closePath(); ctx.fill()
    ctx.beginPath(); ctx.moveTo(cx + w - 4, cy - 108); ctx.lineTo(cx + w + 30, cy - 194); ctx.lineTo(cx + 26, cy - 126); ctx.closePath(); ctx.fill()
  }

  if (looks.muzzle) {
    ctx.save()
    ctx.fillStyle = skinLight
    ctx.beginPath(); ctx.ellipse(cx, cy + 58, 34, 28, 0, 0, 7); ctx.fill()
    ctx.fillStyle = 'rgba(20,12,12,0.9)'
    ctx.beginPath(); ctx.ellipse(cx, cy + 45, 11, 7, 0, 0, 7); ctx.fill()
    ctx.strokeStyle = 'rgba(30,18,15,0.6)'; ctx.lineWidth = 1.5
    ctx.beginPath(); ctx.moveTo(cx, cy + 52); ctx.lineTo(cx, cy + 65); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx, cy + 65); ctx.quadraticCurveTo(cx - 12, cy + 75, cx - 18, cy + 64); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(cx, cy + 65); ctx.quadraticCurveTo(cx + 12, cy + 75, cx + 18, cy + 64); ctx.stroke()
    ctx.restore()
  }

  if (looks.headgear === 'crown' || looks.crown) {
    ctx.fillStyle = '#141318'
    ctx.strokeStyle = '#d8ab3c'; ctx.lineWidth = 3
    ctx.beginPath()
    ctx.moveTo(cx - 58, cy - 100)
    ctx.lineTo(cx - 52, cy - 152); ctx.lineTo(cx - 26, cy - 122); ctx.lineTo(cx, cy - 176)
    ctx.lineTo(cx + 26, cy - 122); ctx.lineTo(cx + 52, cy - 152); ctx.lineTo(cx + 58, cy - 100)
    ctx.closePath(); ctx.fill(); ctx.stroke()
    ctx.fillStyle = '#37c8ff'
    for (let i = 0; i < 3; i++) { ctx.beginPath(); ctx.arc(cx - 34 + i * 34, cy - 112, 4.5, 0, 7); ctx.fill() }
  }

  if (looks.headgear === 'jester' || looks.joker) {
    ctx.fillStyle = '#3a1c56'
    ctx.beginPath(); ctx.moveTo(cx - w + 4, cy - 86); ctx.lineTo(cx - 88, cy - 210); ctx.lineTo(cx - 10, cy - 118); ctx.closePath(); ctx.fill()
    ctx.fillStyle = '#285c30'
    ctx.beginPath(); ctx.moveTo(cx + w - 4, cy - 86); ctx.lineTo(cx + 88, cy - 210); ctx.lineTo(cx + 10, cy - 118); ctx.closePath(); ctx.fill()
    ctx.fillStyle = '#c9b04a'
    ctx.beginPath(); ctx.arc(cx - 88, cy - 214, 10, 0, 7); ctx.fill()
    ctx.beginPath(); ctx.arc(cx + 88, cy - 214, 10, 0, 7); ctx.fill()
    // face paint diamonds
    ctx.fillStyle = 'rgba(180,20,40,0.6)'
    ctx.save(); ctx.translate(cx - 44, cy - 38); ctx.rotate(Math.PI / 4); ctx.fillRect(-9, -9, 18, 18); ctx.restore()
    ctx.save(); ctx.translate(cx + 44, cy - 38); ctx.rotate(Math.PI / 4); ctx.fillRect(-9, -9, 18, 18); ctx.restore()
  }

  if (looks.headgear === 'goggles') {
    ctx.fillStyle = 'rgba(20,18,20,0.9)'
    ctx.beginPath(); ctx.roundRect(cx - w - 4, cy - 44, w * 2 + 8, 34, 8); ctx.fill()
    ctx.strokeStyle = '#5b5044'; ctx.lineWidth = 2; ctx.stroke()
    ctx.fillStyle = 'rgba(90,180,200,0.4)'
    ctx.beginPath(); ctx.ellipse(cx - 24, cy - 27, 17, 11, 0, 0, 7); ctx.fill()
    ctx.beginPath(); ctx.ellipse(cx + 24, cy - 27, 17, 11, 0, 0, 7); ctx.fill()
  }

  if (looks.headgear === 'bandana') {
    ctx.fillStyle = '#7a1d1d'
    ctx.beginPath(); ctx.moveTo(cx - w - 4, cy - 58); ctx.lineTo(cx + w + 4, cy - 58); ctx.lineTo(cx + w + 1, cy - 84); ctx.lineTo(cx - w - 1, cy - 84); ctx.fill()
    ctx.fillStyle = '#5e1414'
    ctx.beginPath(); ctx.moveTo(cx + w + 1, cy - 74); ctx.lineTo(cx + w + 38, cy - 48); ctx.lineTo(cx + w + 24, cy - 92); ctx.fill()
  }

  // small blood spatter
  if (opts.gore !== 'off') {
    ctx.save()
    ctx.globalAlpha = 0.65
    const gc = opts.gore === 'zombie' ? 'rgba(90,150,50,0.8)' : 'rgba(130,18,20,0.8)'
    ctx.fillStyle = gc
    for (let i = 0; i < 7; i++) {
      ctx.beginPath(); ctx.arc(80 + rnd() * 360, 60 + rnd() * 420, 1 + rnd() * 5, 0, 7); ctx.fill()
    }
    ctx.restore()
  }

  // vignette
  const vg = ctx.createRadialGradient(cx, cy, 120, cx, cy, 320)
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.7)')
  ctx.fillStyle = vg; ctx.fillRect(0, 0, 512, 512)

  return canvas
}

function eyeStyleHeight(style, female) {
  if (style === 'cyber') return 7
  if (style === 'hollow') return 12
  return female ? 8 : 7
}

export function portraitDataURL(looks, opts = {}) {
  const c = document.createElement('canvas')
  drawPortrait(c, looks, opts)
  return c.toDataURL('image/png')
}

import * as THREE from 'three'

const geoCache = new Map()
function box(w, h, d) {
  const k = `b${w}_${h}_${d}`
  if (!geoCache.has(k)) geoCache.set(k, new THREE.BoxGeometry(w, h, d))
  return geoCache.get(k)
}

function mat(color, opts = {}) {
  return new THREE.MeshLambertMaterial({ color, ...opts })
}

function addBox(g, w, h, d, x, y, z, material) {
  const m = new THREE.Mesh(box(w, h, d), material)
  m.position.set(x, y, z)
  g.add(m)
  return m
}

function wheel(x, z, r, w, dark, rim) {
  const group = new THREE.Group()
  const tireGeo = new THREE.CylinderGeometry(r, r, w, 12)
  const tire = new THREE.Mesh(tireGeo, dark)
  tire.rotation.z = Math.PI / 2
  tire.castShadow = false
  group.add(tire)
  const rimGeo = new THREE.CylinderGeometry(r * 0.56, r * 0.56, w + 0.02, 8)
  const rm = new THREE.Mesh(rimGeo, rim)
  rm.rotation.z = Math.PI / 2
  group.add(rm)
  for (let i = 0; i < 5; i++) {
    const spoke = addBox(group, 0.02, r * 0.86, 0.09, 0, 0, 0, rim)
    spoke.rotation.x = (i / 5) * Math.PI
  }
  group.position.set(x, r, z)
  return group
}

export function buildCar(vehicle, opts = {}) {
  const v = vehicle || {}
  const color = new THREE.Color(v.color || '#7b3b2a')
  const accent = new THREE.Color(v.accent || '#d9a441')
  const bodyMat = mat(color)
  const darkMat = mat('#141416')
  const glassMat = mat('#10151c', { transparent: true, opacity: 0.9 })
  const accentMat = mat(accent, { emissive: accent.clone().multiplyScalar(0.5) })
  const lightMat = new THREE.MeshBasicMaterial({ color: '#fff4cf' })
  const tailMat = new THREE.MeshBasicMaterial({ color: '#ff2b1d' })
  const rimMat = mat('#8a8478')
  const group = new THREE.Group()
  const shape = v.shape || 'muscle'
  const wheels = []

  if (shape === 'truck') {
    addBox(group, 2.3, 0.55, 4.7, 0, 0.78, 0, bodyMat)
    addBox(group, 2.35, 0.5, 2.5, 0, 1.16, -0.9, bodyMat)
    addBox(group, 2.0, 0.62, 1.25, 0, 1.22, 1.55, bodyMat)
    addBox(group, 1.85, 0.5, 1.35, 0, 1.7, -0.9, glassMat)
    addBox(group, 2.36, 0.16, 4.75, 0, 0.52, 0, darkMat)
    addBox(group, 2.5, 0.18, 0.4, 0, 0.86, 2.3, darkMat) // bull bar
    addBox(group, 0.22, 0.55, 0.22, -0.9, 0.85, 2.35, darkMat)
    addBox(group, 0.22, 0.55, 0.22, 0.9, 0.85, 2.35, darkMat)
    addBox(group, 0.35, 0.55, 2.4, 0, 1.5, -0.9, accentMat) // roof rack
    for (const x of [-0.98, 0.98]) for (const z of [-1.6, 1.65]) wheels.push(wheel(x, z, 0.56, 0.42, darkMat, rimMat))
    // exhaust stacks
    addBox(group, 0.16, 0.85, 0.16, -0.85, 1.65, -0.2, rimMat)
    addBox(group, 0.16, 0.85, 0.16, 0.85, 1.65, -0.2, rimMat)
  } else if (shape === 'buggy') {
    addBox(group, 2.1, 0.42, 3.7, 0, 0.78, 0, bodyMat)
    addBox(group, 1.5, 0.45, 1.5, 0, 1.16, -0.55, bodyMat)
    addBox(group, 1.7, 0.52, 0.9, 0, 1.13, 0.9, bodyMat)
    addBox(group, 1.3, 0.4, 1.15, 0, 1.53, -0.55, glassMat)
    // roll bars
    const barMat = mat('#35383a')
    addBox(group, 2.0, 0.1, 0.1, 0, 1.62, -0.4, barMat)
    addBox(group, 0.1, 0.7, 0.1, -0.95, 1.3, -0.4, barMat)
    addBox(group, 0.1, 0.7, 0.1, 0.95, 1.3, -0.4, barMat)
    addBox(group, 0.1, 0.7, 0.1, -0.95, 1.3, 0.5, barMat)
    addBox(group, 0.1, 0.7, 0.1, 0.95, 1.3, 0.5, barMat)
    addBox(group, 2.1, 0.14, 0.18, 0, 1.1, 1.9, accentMat)
    for (const x of [-1.08, 1.08]) for (const z of [-1.42, 1.42]) wheels.push(wheel(x, z, 0.62, 0.5, darkMat, accentMat))
  } else if (shape === 'sedan') {
    addBox(group, 2.08, 0.52, 4.35, 0, 0.73, 0, bodyMat)
    addBox(group, 1.86, 0.55, 2.1, 0, 1.15, -0.15, bodyMat)
    addBox(group, 1.7, 0.38, 1.85, 0, 1.5, -0.15, glassMat)
    addBox(group, 2.02, 0.12, 4.4, 0, 0.55, 0, darkMat)
    addBox(group, 1.5, 0.12, 0.8, 0, 1.22, -2.1, accentMat)
    for (const x of [-1.02, 1.02]) for (const z of [-1.42, 1.42]) wheels.push(wheel(x, z, 0.48, 0.34, darkMat, rimMat))
  } else if (shape === 'exotic') {
    addBox(group, 2.2, 0.36, 4.5, 0, 0.62, 0, bodyMat)
    addBox(group, 1.55, 0.48, 1.65, 0, 1.02, -0.45, bodyMat)
    addBox(group, 1.35, 0.32, 1.35, 0, 1.32, -0.45, glassMat)
    addBox(group, 1.7, 0.2, 1.2, 0, 0.83, 1.5, bodyMat) // wedge hood
    addBox(group, 2.24, 0.09, 1.45, 0, 0.84, -1.95, accentMat) // wing
    addBox(group, 0.12, 0.42, 0.3, -0.92, 0.76, -1.95, accentMat)
    addBox(group, 0.12, 0.42, 0.3, 0.92, 0.76, -1.95, accentMat)
    addBox(group, 1.9, 0.08, 0.55, 0, 0.38, 2.35, darkMat) // splitter
    for (const x of [-1.06, 1.06]) for (const z of [-1.5, 1.46]) wheels.push(wheel(x, z, 0.5, 0.38, darkMat, accentMat))
  } else {
    // muscle
    addBox(group, 2.16, 0.5, 4.4, 0, 0.72, 0, bodyMat)
    addBox(group, 1.78, 0.52, 2.0, 0, 1.13, -0.35, bodyMat)
    addBox(group, 1.6, 0.38, 1.7, 0, 1.45, -0.35, glassMat)
    addBox(group, 1.7, 0.18, 1.35, 0, 0.86, 1.55, bodyMat)
    addBox(group, 2.0, 0.4, 0.14, 0, 0.5, 2.28, darkMat) // grille
    addBox(group, 1.75, 0.06, 0.6, 0, 0.52, -2.15, accentMat) // rear diffuser
    addBox(group, 0.18, 0.08, 1.1, -0.72, 1.0, 1.25, accentMat) // hood stripe
    addBox(group, 0.18, 0.08, 1.1, 0.72, 1.0, 1.25, accentMat)
    for (const x of [-1.02, 1.02]) for (const z of [-1.45, 1.48]) wheels.push(wheel(x, z, 0.49, 0.36, darkMat, rimMat))
  }

  // lights
  const yFront = shape === 'truck' ? 1.28 : shape === 'buggy' ? 1.05 : 0.8
  const zFront = shape === 'truck' ? 2.38 : shape === 'buggy' ? 1.92 : 2.27
  for (const x of [-0.68, 0.68]) {
    addBox(group, 0.34, 0.16, 0.08, x, yFront, zFront, lightMat)
    if (shape !== 'exotic') addBox(group, 0.36, 0.16, 0.08, x, yFront, -2.27, tailMat)
  }
  if (shape === 'exotic') {
    addBox(group, 1.8, 0.1, 0.05, 0, 0.78, 2.26, new THREE.MeshBasicMaterial({ color: '#bfeaff' }))
    addBox(group, 1.7, 0.08, 0.05, 0, 0.78, -2.28, tailMat)
    // glowing underlight
    const glow = new THREE.Mesh(new THREE.PlaneGeometry(2.5, 4.8), new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.22, depthWrite: false }))
    glow.rotation.x = -Math.PI / 2
    glow.position.y = 0.13
    group.add(glow)
  }

  // spikes / battle damage flavor
  if (v.spikes || v.shape === 'truck' || v.id === 'wool_reaper' || v.id === 'beast_titan') {
    const spikeMat = mat('#b9b0a0')
    for (let i = 0; i < 5; i++) {
      const s = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.42, 5), spikeMat)
      s.position.set(-0.8 + i * 0.4, 1.22, 2.2)
      s.rotation.x = Math.PI / 2
      group.add(s)
    }
  }

  // decals / roof number
  if (opts.boss) {
    const fin = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.7, 4), accentMat)
    fin.position.set(0, 1.65, -0.35)
    group.add(fin)
  }

  // headlight cone in menu, not race
  if (opts.beams) {
    for (const x of [-0.55, 0.55]) {
      const cone = new THREE.Mesh(
        new THREE.ConeGeometry(1.4, 9, 12, 1, true),
        new THREE.MeshBasicMaterial({ color: '#ffe7a8', transparent: true, opacity: 0.045, depthWrite: false, side: THREE.DoubleSide })
      )
      cone.rotation.x = Math.PI / 2
      cone.position.set(x, 0.8, 6.9)
      group.add(cone)
    }
  }

  group.userData.wheels = wheels
  group.userData.bodyMat = bodyMat
  group.userData.accentMat = accentMat
  group.userData.tailMat = tailMat
  group.traverse(o => { if (o.isMesh) { o.frustumCulled = true } })
  return group
}

export function spinWheels(car, speed, dt) {
  const wheels = car?.userData?.wheels
  if (!wheels) return
  const spin = speed * dt * 1.9
  for (const w of wheels) w.children[0].rotation.y += spin
}

export function makeSkidMark(color = '#1a1a1a') {
  const g = new THREE.PlaneGeometry(0.32, 1.4)
  const m = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.34, depthWrite: false })
  return new THREE.Mesh(g, m)
}

import * as THREE from 'three'
import { buildCar } from './car.js'
import { VEHICLES } from './data.js'

function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0
    let t = Math.imul(a ^ a >>> 15, 1 | a)
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
    return ((t ^ t >>> 14) >>> 0) / 4294967296
  }
}

function moonTexture() {
  const c = document.createElement('canvas')
  c.width = c.height = 256
  const x = c.getContext('2d')
  const g = x.createRadialGradient(128, 118, 10, 128, 128, 116)
  g.addColorStop(0, '#ffd9a6'); g.addColorStop(0.42, '#e97b42'); g.addColorStop(0.78, '#9e2d22'); g.addColorStop(1, 'rgba(70,10,12,0)')
  x.fillStyle = g; x.beginPath(); x.arc(128, 128, 126, 0, 7); x.fill()
  x.globalCompositeOperation = 'multiply'
  x.fillStyle = 'rgba(60,15,15,0.4)'
  for (let i = 0; i < 16; i++) {
    x.beginPath(); x.arc(60 + Math.random() * 140, 60 + Math.random() * 140, 3 + Math.random() * 14, 0, 7); x.fill()
  }
  // skull impression
  x.globalCompositeOperation = 'source-over'
  x.fillStyle = 'rgba(55,10,12,0.35)'
  x.beginPath(); x.ellipse(128, 120, 48, 55, 0, 0, 7); x.fill()
  x.beginPath(); x.ellipse(110, 112, 13, 17, 0, 0, 7); x.fill()
  x.beginPath(); x.ellipse(146, 112, 13, 17, 0, 0, 7); x.fill()
  x.fillRect(122, 134, 12, 20)
  x.fillStyle = 'rgba(55,10,12,0.25)'
  for (let i = 0; i < 5; i++) x.fillRect(112 + i * 7, 158, 4, 18)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export class MenuBackdrop {
  constructor(canvas) {
    this.canvas = canvas
    this.active = false
    this.quality = 'medium'
    this.clock = new THREE.Clock()
    this.flash = 0
    this.nextBolt = 2.5
    this.t = 0
    this.init()
  }

  init() {
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, alpha: true, antialias: this.quality !== 'low', powerPreference: 'high-performance' })
    this.renderer.setClearColor(0x000000, 0)
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.scene = new THREE.Scene()
    this.scene.fog = new THREE.FogExp2(0x1c1210, 0.017)
    this.camera = new THREE.PerspectiveCamera(47, 2, 0.5, 260)
    this.camera.position.set(0, 5.4, 19)
    this.camera.lookAt(0, 2.2, 0)

    const hemi = new THREE.HemisphereLight(0x8899bb, 0x2a1510, 0.55)
    this.scene.add(hemi)
    this.moonLight = new THREE.DirectionalLight(0xff7c45, 1.4)
    this.moonLight.position.set(-18, 20, -30)
    this.scene.add(this.moonLight)
    this.rim = new THREE.PointLight(0xff5a2b, 2.2, 60)
    this.rim.position.set(-8, 4, 2)
    this.scene.add(this.rim)
    this.blue = new THREE.PointLight(0x3b9fd6, 1.5, 35)
    this.blue.position.set(7, 3, -1)
    this.scene.add(this.blue)

    // ground + road
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(320, 320), new THREE.MeshLambertMaterial({ color: 0x1b1817 }))
    ground.rotation.x = -Math.PI / 2
    this.scene.add(ground)
    const road = new THREE.Mesh(new THREE.PlaneGeometry(16, 150), new THREE.MeshLambertMaterial({ color: 0x242221 }))
    road.rotation.x = -Math.PI / 2
    road.position.set(4, 0.02, -55)
    road.rotation.z = -0.06
    this.scene.add(road)
    for (let i = 0; i < 16; i++) {
      const line = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 3.5), new THREE.MeshBasicMaterial({ color: 0xb99b52 }))
      line.rotation.x = -Math.PI / 2
      line.rotation.z = -0.06
      line.position.set(4 + Math.sin(-0.06) * (i * 8 - 50), 0.035, -50 + i * 8)
      line.rotation.z = -0.06
      this.scene.add(line)
    }
    // road edges
    for (const side of [-1, 1]) {
      const edge = new THREE.Mesh(new THREE.PlaneGeometry(0.6, 150), new THREE.MeshBasicMaterial({ color: 0x6d5a36 }))
      edge.rotation.x = -Math.PI / 2
      edge.position.set(4 + side * 8, 0.03, -55)
      edge.rotation.z = -0.06
      this.scene.add(edge)
    }

    // ruined skyline
    const rnd = mulberry32(1337)
    const bMat = new THREE.MeshLambertMaterial({ color: 0x100e0e })
    const bMat2 = new THREE.MeshLambertMaterial({ color: 0x171211 })
    for (let i = 0; i < 44; i++) {
      const side = rnd() > 0.5 ? 1 : -1
      const w = 4 + rnd() * 12
      const h = 10 + rnd() * 44
      const d = 4 + rnd() * 12
      const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), rnd() > 0.5 ? bMat : bMat2)
      b.position.set(side * (24 + rnd() * 55), h / 2, -25 - rnd() * 85)
      b.rotation.y = rnd() * 0.5
      this.scene.add(b)
      // broken top
      if (rnd() > 0.6) {
        const top = new THREE.Mesh(new THREE.BoxGeometry(w * 0.6, 3 + rnd() * 6, d * 0.6), bMat)
        top.position.set(b.position.x + side * 2, h + 2, b.position.z)
        top.rotation.z = (rnd() - 0.5) * 0.5
        this.scene.add(top)
      }
      // windows
      if (rnd() > 0.35) {
        const win = new THREE.Mesh(new THREE.PlaneGeometry(0.7, 0.55), new THREE.MeshBasicMaterial({ color: rnd() > 0.7 ? 0x9b3a1f : 0x5a4c37 }))
        win.position.set(b.position.x - side * w * 0.51, h * 0.55, b.position.z + d * 0.51)
        win.rotation.y = side > 0 ? -0.02 : 0.02
        this.scene.add(win)
      }
    }
    // foreground rubble
    for (let i = 0; i < 28; i++) {
      const r = 0.3 + rnd() * 1.6
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(r, 0), new THREE.MeshLambertMaterial({ color: 0x2a2320, flatShading: true }))
      rock.position.set((rnd() - 0.5) * 50, r * 0.4, 4 + rnd() * 18)
      rock.rotation.set(rnd() * 3, rnd() * 3, rnd() * 3)
      this.scene.add(rock)
    }

    // moon
    const moon = new THREE.Mesh(new THREE.PlaneGeometry(34, 34), new THREE.MeshBasicMaterial({ map: moonTexture(), transparent: true, depthWrite: false, fog: false }))
    moon.position.set(-17, 20, -78)
    this.scene.add(moon)
    this.moon = moon

    // hero car
    const heroV = { ...VEHICLES[0], color: '#4a2018', accent: '#d9a441' }
    this.hero = buildCar(heroV, { beams: true, boss: true })
    this.hero.position.set(3.5, 0.15, 3.6)
    this.hero.rotation.y = -0.38
    this.hero.scale.setScalar(1.15)
    this.scene.add(this.hero)
    const carLight = new THREE.PointLight(0xff6b2b, 2.4, 14)
    carLight.position.set(3, 1.6, 4)
    this.scene.add(carLight)
    // dust under car
    const dust = new THREE.Mesh(new THREE.CircleGeometry(3.8, 24), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.4, depthWrite: false }))
    dust.rotation.x = -Math.PI / 2
    dust.position.set(3.5, 0.06, 3.6)
    this.scene.add(dust)

    // chain silhouettes hanging from sky
    this.chains = []
    for (let c = 0; c < 3; c++) {
      const x = -32 + c * 24 + rnd() * 8
      const pts = []
      for (let i = 0; i < 10; i++) pts.push(new THREE.Vector3(x + Math.sin(i * 0.7) * 0.3, 30 - i * 2.2, -18 - c * 8))
      const geo = new THREE.BufferGeometry().setFromPoints(pts)
      const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: 0x39322b }))
      this.scene.add(line)
    }

    // rain
    this.rainCount = 1400
    const pos = new Float32Array(this.rainCount * 3)
    for (let i = 0; i < this.rainCount; i++) {
      pos[i * 3] = (rnd() - 0.5) * 90
      pos[i * 3 + 1] = rnd() * 35
      pos[i * 3 + 2] = -20 + (rnd() - 0.5) * 70
    }
    const rainGeo = new THREE.BufferGeometry()
    rainGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    this.rain = new THREE.Points(rainGeo, new THREE.PointsMaterial({ color: 0x8aa2ad, size: 0.1, transparent: true, opacity: 0.5, depthWrite: false }))
    this.scene.add(this.rain)

    // embers
    this.emberCount = 220
    const ep = new Float32Array(this.emberCount * 3)
    for (let i = 0; i < this.emberCount; i++) {
      ep[i * 3] = (rnd() - 0.5) * 60
      ep[i * 3 + 1] = rnd() * 20
      ep[i * 3 + 2] = -30 + rnd() * 40
    }
    const eGeo = new THREE.BufferGeometry(); eGeo.setAttribute('position', new THREE.BufferAttribute(ep, 3))
    this.embers = new THREE.Points(eGeo, new THREE.PointsMaterial({ color: 0xff6a2a, size: 0.18, transparent: true, opacity: 0.8, depthWrite: false }))
    this.scene.add(this.embers)

    // lightning line
    this.boltMat = new THREE.LineBasicMaterial({ color: 0xd9e6ff, transparent: true, opacity: 0 })
    this.bolt = new THREE.Line(new THREE.BufferGeometry(), this.boltMat)
    this.bolt.frustumCulled = false
    this.scene.add(this.bolt)
    this.flashLight = new THREE.PointLight(0xbdd8ff, 0, 160)
    this.flashLight.position.set(-15, 28, -35)
    this.scene.add(this.flashLight)

    this.resize()
  }

  setQuality(q) {
    this.quality = q
    if (!this.renderer) return
    this.renderer.setPixelRatio(q === 'low' ? 1 : q === 'high' ? Math.min(2, window.devicePixelRatio || 1) : Math.min(1.5, window.devicePixelRatio || 1))
    this.rain.visible = q !== 'low'
    this.embers.visible = q !== 'low'
    this.resize()
  }

  resize() {
    if (!this.renderer) return
    const w = window.innerWidth, h = window.innerHeight
    this.renderer.setSize(w, h, false)
    this.renderer.setPixelRatio(this.quality === 'low' ? 1 : Math.min(this.quality === 'high' ? 2 : 1.5, window.devicePixelRatio || 1))
    this.camera.aspect = w / h
    this.camera.fov = w / h < 0.85 ? 58 : 47
    this.camera.updateProjectionMatrix()
  }

  start() {
    if (this.active) return
    this.active = true
    this.clock.getDelta()
    this.loop()
  }

  stop() {
    this.active = false
    if (this.raf) cancelAnimationFrame(this.raf)
  }

  loop() {
    if (!this.active) return
    this.raf = requestAnimationFrame(() => this.loop())
    const dt = Math.min(0.05, this.clock.getDelta())
    this.t += dt
    const t = this.t
    this.camera.position.x = Math.sin(t * 0.09) * 1.8
    this.camera.position.y = 5.4 + Math.sin(t * 0.16) * 0.22
    this.camera.lookAt(0, 2.2 + Math.sin(t * 0.1) * 0.1, 0)
    this.hero.position.y = 0.15 + Math.sin(t * 0.8) * 0.012
    this.hero.rotation.z = Math.sin(t * 0.6) * 0.004
    this.rim.intensity = 1.6 + Math.sin(t * 3.2) * 0.45
    this.blue.intensity = 1.2 + Math.sin(t * 2.1 + 1) * 0.4

    // rain
    if (this.rain.visible) {
      const p = this.rain.geometry.attributes.position.array
      for (let i = 0; i < this.rainCount; i++) {
        p[i * 3 + 1] -= (18 + (i % 5)) * dt
        p[i * 3] += 4.2 * dt
        if (p[i * 3 + 1] < 0) {
          p[i * 3 + 1] = 35
          p[i * 3] = (Math.random() - 0.5) * 90
          p[i * 3 + 2] = -20 + (Math.random() - 0.5) * 70
        }
      }
      this.rain.geometry.attributes.position.needsUpdate = true
    }
    if (this.embers.visible) {
      const e = this.embers.geometry.attributes.position.array
      for (let i = 0; i < this.emberCount; i++) {
        e[i * 3 + 1] += (0.8 + (i % 4) * 0.4) * dt
        e[i * 3] += Math.sin(t + i) * 0.1 * dt
        if (e[i * 3 + 1] > 24) e[i * 3 + 1] = 0
      }
      this.embers.geometry.attributes.position.needsUpdate = true
    }

    // lightning
    this.nextBolt -= dt
    if (this.flash > 0) {
      this.flash = Math.max(0, this.flash - dt * 2.6)
      this.flashLight.intensity = this.flash * 11
      this.moonLight.intensity = 1.4 + this.flash * 2.5
      this.boltMat.opacity = this.flash
    } else {
      this.boltMat.opacity = 0
      this.flashLight.intensity = 0
      this.moonLight.intensity = 1.4
    }
    if (this.nextBolt <= 0) {
      this.nextBolt = 4 + Math.random() * 8
      this.makeBolt()
    }

    this.renderer.render(this.scene, this.camera)
  }

  makeBolt() {
    const x0 = (Math.random() - 0.5) * 50
    const z0 = -45 - Math.random() * 30
    const pts = [new THREE.Vector3(x0, 32, z0)]
    let x = x0, y = 32, z = z0
    for (let i = 0; i < 9; i++) {
      x += (Math.random() - 0.5) * 5
      y -= 2.7 + Math.random() * 2
      z += (Math.random() - 0.5) * 2
      pts.push(new THREE.Vector3(x, y, z))
    }
    this.bolt.geometry.dispose()
    this.bolt.geometry = new THREE.BufferGeometry().setFromPoints(pts)
    this.flash = 0.9
    this.flashLight.position.set(x0, 24, z0)
  }
}

import * as THREE from 'three'
import { TERRAINS, WEATHERS } from './data.js'

const N_SAMPLES = 720

function rng(seed) {
  let a = seed >>> 0
  return () => {
    a += 0x6D2B79F5
    let t = a
    t = Math.imul(t ^ t >>> 15, t | 1)
    t ^= t + Math.imul(t ^ t >>> 7, t | 61)
    return ((t ^ t >>> 14) >>> 0) / 4294967296
  }
}

function makeRoadTexture(terrain) {
  const c = document.createElement('canvas')
  c.width = 256; c.height = 512
  const x = c.getContext('2d')
  x.fillStyle = terrain.road
  x.fillRect(0, 0, 256, 512)
  // asphalt grain
  const r = rng(terrain.id.length * 7001 + 11)
  for (let i = 0; i < 4500; i++) {
    const v = 20 + Math.floor(r() * 55)
    x.fillStyle = `rgba(${v},${v - 3},${v - 4},${0.1 + r() * 0.22})`
    x.fillRect(r() * 256, r() * 512, 1 + r() * 3, 1 + r() * 2)
  }
  // cracks
  x.strokeStyle = 'rgba(4,4,5,0.45)'
  for (let i = 0; i < 12; i++) {
    x.lineWidth = 0.8 + r() * 1.8
    let px = r() * 256, py = r() * 512
    x.beginPath(); x.moveTo(px, py)
    for (let j = 0; j < 5; j++) { px += (r() - 0.5) * 26; py += 10 + r() * 30; x.lineTo(px, py) }
    x.stroke()
  }
  // edge lines
  x.fillStyle = 'rgba(205,188,142,0.55)'
  x.fillRect(12, 0, 3, 512)
  x.fillRect(241, 0, 3, 512)
  // center dashed line
  x.fillStyle = 'rgba(216,182,92,0.66)'
  for (let i = 0; i < 6; i++) x.fillRect(125, i * 86 + 12, 6, 50)
  // oil / blood stains
  x.fillStyle = 'rgba(12,7,6,0.22)'
  for (let i = 0; i < 8; i++) { x.beginPath(); x.ellipse(r() * 256, r() * 512, 6 + r() * 24, 4 + r() * 13, r() * 3, 0, 7); x.fill() }
  const tex = new THREE.CanvasTexture(c)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 4
  return tex
}

function makeBannerTexture() {
  const c = document.createElement('canvas'); c.width = 512; c.height = 128
  const x = c.getContext('2d')
  x.fillStyle = '#120c0b'; x.fillRect(0, 0, 512, 128)
  x.fillStyle = '#a3151b'; x.fillRect(0, 0, 512, 10); x.fillRect(0, 118, 512, 10)
  for (let i = 0; i < 16; i++) { x.fillStyle = i % 2 ? '#d9c89a' : '#161212'; x.fillRect(i * 32, 104, 32, 24) }
  x.font = 'bold 66px Impact, Arial Black, sans-serif'
  x.fillStyle = '#e8dcc0'; x.textAlign = 'center'
  x.fillText('HELLRIDE', 256, 76)
  x.font = 'bold 22px monospace'; x.fillStyle = '#d03a2a'
  x.fillText('S T A R T   /   F I N I S H', 256, 100)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  return t
}

function makeSunTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 256
  const x = c.getContext('2d')
  const g = x.createRadialGradient(128, 128, 2, 128, 128, 128)
  g.addColorStop(0, 'rgba(255,238,190,1)'); g.addColorStop(0.14, 'rgba(255,185,100,0.9)'); g.addColorStop(0.5, 'rgba(210,80,40,0.18)'); g.addColorStop(1, 'rgba(120,30,20,0)')
  x.fillStyle = g; x.fillRect(0, 0, 256, 256)
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace
  return t
}

function makeSkyMaterial(top, horizon) {
  return new THREE.ShaderMaterial({
    uniforms: { topColor: { value: new THREE.Color(top) }, horizonColor: { value: new THREE.Color(horizon) } },
    vertexShader: 'varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
    fragmentShader: `uniform vec3 topColor; uniform vec3 horizonColor; varying vec3 vPos;
      void main(){ float h = clamp(normalize(vPos).y * 1.4 + 0.15, 0.0, 1.0); vec3 c = mix(horizonColor, topColor, pow(h, 0.72)); gl_FragColor = vec4(c, 1.0); }`,
    side: THREE.BackSide, depthWrite: false, fog: false
  })
}

function dummyMatrix(obj) {
  obj.updateMatrix()
  return obj.matrix
}

export class Track {
  constructor({ terrain = 'wasteland', weather = 'cloudy', seed = 1, quality = 'medium' } = {}) {
    this.terrain = TERRAINS.find(t => t.id === terrain) || TERRAINS[0]
    this.weather = WEATHERS.find(w => w.id === weather) || WEATHERS[0]
    this.seed = seed
    this.quality = quality
    this.rand = rng(seed * 7919 + this.terrain.id.length * 131 + this.weather.id.length * 17)
    this.width = 15.5
    this.group = new THREE.Group()
    this.t = 0
    this.buildCurve()
    this.buildEnvironment()
    this.buildRoad()
    this.buildGate()
    this.buildProps()
    this.buildWeather()
  }

  buildCurve() {
    const r = this.rand
    const count = 11
    const pts = []
    const baseR = 100 + r() * 36
    for (let i = 0; i < count; i++) {
      const a = (i / count) * Math.PI * 2 + (r() - 0.5) * 0.2
      const radius = baseR * (0.72 + r() * 0.63)
      const elev = (this.terrain.elevation || 2) * (0.4 + 0.6 * Math.sin(a * 3 + r() * 0.7)) * (this.terrain.id === 'mountains' || this.terrain.id === 'volcano' ? 1 : 0.35)
      pts.push(new THREE.Vector3(Math.cos(a) * radius, elev, Math.sin(a) * radius))
    }
    pts.push(pts[0].clone())
    this.curve = new THREE.CatmullRomCurve3(pts, true, 'catmullrom', 0.5)
    this.samples = []
    for (let i = 0; i < N_SAMPLES; i++) {
      const t = i / N_SAMPLES
      const p = this.curve.getPointAt(t)
      const tan = this.curve.getTangentAt(t)
      tan.y = 0
      tan.normalize()
      const right = new THREE.Vector3(-tan.z, 0, tan.x)
      this.samples.push({ p, tan, right })
    }
    // smooth surface height to avoid nausea
    const raw = this.samples.map(s => s.p.y)
    for (let iter = 0; iter < 3; iter++) {
      for (let i = 0; i < N_SAMPLES; i++) {
        const a = raw[(i - 1 + N_SAMPLES) % N_SAMPLES], b = raw[i], c = raw[(i + 1) % N_SAMPLES]
        raw[i] = (a + b * 2 + c) / 4
      }
    }
    this.computeLength()
    this.samples.forEach((s, i) => { s.p.y = raw[i] })
  }

  computeLength() {
    let len = 0
    for (let i = 0; i < N_SAMPLES; i++) {
      const a = this.samples[i].p, b = this.samples[(i + 1) % N_SAMPLES].p
      len += a.distanceTo(b)
    }
    this.length = len
  }

  buildEnvironment() {
    const t = this.terrain, w = this.weather
    this.skyColor = new THREE.Color(t.sky)
    this.horizonColor = new THREE.Color(t.horizon).lerp(new THREE.Color(w.tint), 0.25)
    this.fogColor = new THREE.Color(t.fog).lerp(new THREE.Color(w.tint), 0.35)
    this.skyMat = makeSkyMaterial('#' + this.skyColor.getHexString(), '#' + this.horizonColor.getHexString())
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(450, 24, 12), this.skyMat)
    this.group.add(this.sky)

    const sun = new THREE.Mesh(new THREE.PlaneGeometry(55, 55), new THREE.MeshBasicMaterial({ map: makeSunTexture(), transparent: true, depthWrite: false, fog: false }))
    sun.position.set(-140, 90, -210)
    sun.lookAt(0, 0, 0)
    this.group.add(sun)
    this.sun = sun

    const hemi = new THREE.HemisphereLight(0xa4b5c8, new THREE.Color(t.ground).multiplyScalar(0.38), 0.9)
    this.group.add(hemi)
    this.hemi = hemi
    const dir = new THREE.DirectionalLight(0xffb27a, 1.35)
    dir.position.set(-60, 90, -40)
    this.group.add(dir)
    this.dir = dir
    const fill = new THREE.DirectionalLight(0x7890b8, 0.5)
    fill.position.set(40, 30, 60)
    this.group.add(fill)

    // ground
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(600, 600, 1, 1), new THREE.MeshLambertMaterial({ color: new THREE.Color(t.ground).multiplyScalar(0.7) }))
    ground.rotation.x = -Math.PI / 2
    ground.position.y = -0.6
    this.group.add(ground)
    this.ground = ground

    // distant mountain ring
    const r = this.rand
    const ringMat = new THREE.MeshLambertMaterial({ color: new THREE.Color(t.ground).lerp(this.fogColor, 0.55), flatShading: true })
    for (let i = 0; i < 26; i++) {
      const a = (i / 26) * Math.PI * 2 + r() * 0.15
      const dist = 220 + r() * 80
      const h = 30 + r() * 85
      const cone = new THREE.Mesh(new THREE.ConeGeometry(24 + r() * 40, h, 5 + Math.floor(r() * 2)), ringMat)
      cone.position.set(Math.cos(a) * dist, h * 0.34 - 4, Math.sin(a) * dist)
      cone.rotation.y = r() * 3
      this.group.add(cone)
      this.addDisposable(cone)
    }
    this.addDisposable(ground)
  }

  buildRoad() {
    const { samples, width } = this
    const roadW = width
    const landW = 66
    const positions = [], uvs = [], indices = []
    const landPos = [], landIdx = []
    for (let i = 0; i <= N_SAMPLES; i++) {
      const s = samples[i % N_SAMPLES]
      const y = s.p.y
      const lx = s.p.x - s.right.x * roadW / 2, lz = s.p.z - s.right.z * roadW / 2
      const rx = s.p.x + s.right.x * roadW / 2, rz = s.p.z + s.right.z * roadW / 2
      positions.push(lx, y + 0.06, lz, rx, y + 0.06, rz)
      const v = i * (this.length / N_SAMPLES) / 7
      uvs.push(0, v, 1, v)
      // land: outer low, inner high
      landPos.push(
        s.p.x - s.right.x * landW, y - 0.6, s.p.z - s.right.z * landW,
        s.p.x - s.right.x * (roadW / 2 + 0.7), y - 0.02, s.p.z - s.right.z * (roadW / 2 + 0.7),
        s.p.x + s.right.x * (roadW / 2 + 0.7), y - 0.02, s.p.z + s.right.z * (roadW / 2 + 0.7),
        s.p.x + s.right.x * landW, y - 0.6, s.p.z + s.right.z * landW
      )
    }
    for (let i = 0; i < N_SAMPLES; i++) {
      const a = i * 2, b = a + 1, c = a + 2, d = a + 3
      indices.push(a, c, b, b, c, d)
      const l = i * 4
      // left slope
      landIdx.push(l, l + 4, l + 1, l + 1, l + 4, l + 5)
      // center
      landIdx.push(l + 1, l + 5, l + 2, l + 2, l + 5, l + 6)
      // right slope
      landIdx.push(l + 2, l + 6, l + 3, l + 3, l + 6, l + 7)
    }
    const roadGeo = new THREE.BufferGeometry()
    roadGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    roadGeo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
    roadGeo.setIndex(indices)
    roadGeo.computeVertexNormals()
    const roadMat = new THREE.MeshLambertMaterial({ map: makeRoadTexture(this.terrain), color: '#ffffff' })
    const road = new THREE.Mesh(roadGeo, roadMat)
    this.group.add(road)
    this.road = road
    this.addDisposable(road)

    const landGeo = new THREE.BufferGeometry()
    landGeo.setAttribute('position', new THREE.Float32BufferAttribute(landPos, 3))
    landGeo.setIndex(landIdx)
    landGeo.computeVertexNormals()
    const landMat = new THREE.MeshLambertMaterial({ color: new THREE.Color(this.terrain.ground), flatShading: true })
    const land = new THREE.Mesh(landGeo, landMat)
    this.group.add(land)
    this.land = land
    this.addDisposable(land)

    // edge markers / barrier posts (instanced)
    const postGeo = new THREE.BoxGeometry(0.18, 0.9, 0.18)
    const postMat = new THREE.MeshLambertMaterial({ color: new THREE.Color(this.terrain.accent).multiplyScalar(0.55) })
    const posts = new THREE.InstancedMesh(postGeo, postMat, Math.floor(N_SAMPLES / 10) * 2)
    const dummy = new THREE.Object3D()
    let pi = 0
    for (let i = 0; i < N_SAMPLES; i += 10) {
      const s = samples[i]
      for (const side of [-1, 1]) {
        dummy.position.set(s.p.x + s.right.x * side * (roadW / 2 + 1.2), s.p.y + 0.45, s.p.z + s.right.z * side * (roadW / 2 + 1.2))
        dummy.rotation.y = Math.atan2(s.tan.x, s.tan.z)
        dummy.updateMatrix()
        posts.setMatrixAt(pi++, dummy.matrix)
      }
    }
    posts.count = pi
    this.group.add(posts)
    this.addDisposable(posts)

    // glowing reflectors
    const refGeo = new THREE.SphereGeometry(0.16, 6, 5)
    const refMat = new THREE.MeshBasicMaterial({ color: this.terrain.accent })
    const refs = new THREE.InstancedMesh(refGeo, refMat, 80)
    let ri = 0
    for (let i = 0; i < N_SAMPLES; i += 20) {
      const s = samples[i]
      for (const side of [-1, 1]) {
        dummy.position.set(s.p.x + s.right.x * side * (roadW / 2 + 1.25), s.p.y + 1.02, s.p.z + s.right.z * side * (roadW / 2 + 1.25))
        dummy.rotation.set(0, 0, 0)
        dummy.updateMatrix()
        refs.setMatrixAt(ri++, dummy.matrix)
      }
    }
    refs.count = ri
    this.group.add(refs)
    this.addDisposable(refs)
  }

  buildGate() {
    const s = this.samples[0]
    const yaw = Math.atan2(s.tan.x, s.tan.z)
    const gate = new THREE.Group()
    gate.position.copy(s.p)
    gate.rotation.y = yaw
    const metal = new THREE.MeshLambertMaterial({ color: '#24211f' })
    const red = new THREE.MeshLambertMaterial({ color: '#8f171b' })
    for (const side of [-1, 1]) {
      const pillar = new THREE.Mesh(new THREE.BoxGeometry(1.05, 8, 1.05), metal)
      pillar.position.set(side * 10.5, 4, 0)
      gate.add(pillar)
      const cap = new THREE.Mesh(new THREE.ConeGeometry(0.72, 1.2, 4), red)
      cap.position.set(side * 10.5, 8.6, 0); cap.rotation.y = Math.PI / 4
      gate.add(cap)
    }
    const banner = new THREE.Mesh(new THREE.BoxGeometry(21, 3.1, 0.32), new THREE.MeshBasicMaterial({ map: makeBannerTexture() }))
    banner.position.set(0, 7.3, 0)
    gate.add(banner)
    // checkers on the ground
    const c = document.createElement('canvas'); c.width = 256; c.height = 64
    const cx = c.getContext('2d')
    for (let i = 0; i < 16; i++) for (let j = 0; j < 4; j++) { cx.fillStyle = (i + j) % 2 ? '#e7ddc3' : '#171313'; cx.fillRect(i * 16, j * 16, 16, 16) }
    const tex = new THREE.CanvasTexture(c); tex.colorSpace = THREE.SRGBColorSpace
    const line = new THREE.Mesh(new THREE.PlaneGeometry(this.width, 3.2), new THREE.MeshBasicMaterial({ map: tex }))
    line.rotation.x = -Math.PI / 2
    line.position.y = 0.1
    gate.add(line)
    this.group.add(gate)
    this.gate = gate

    // start lights on gate
    this.startLights = []
    for (let i = 0; i < 3; i++) {
      const l = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 6), new THREE.MeshBasicMaterial({ color: '#3a1010' }))
      l.position.set(-1.8 + i * 1.8, 5.55, 0.25)
      gate.add(l)
      this.startLights.push(l)
    }
  }

  buildProps() {
    const kind = this.terrain.props
    for (const k of kind) this.buildProp(k)
    // roadside wreck clusters
    if (!kind.includes('wreck')) this.buildProp('wreck')
  }

  propPositions(count, min = 18, max = 55) {
    const out = []
    const r = this.rand
    for (let n = 0; n < count; n++) {
      const i = Math.floor(r() * N_SAMPLES)
      const s = this.samples[i]
      const side = r() > 0.5 ? 1 : -1
      const lateral = min + r() * (max - min)
      const baseY = lateral < 36 ? s.p.y - 0.15 : -0.5
      out.push({
        x: s.p.x + s.right.x * side * lateral,
        y: baseY,
        z: s.p.z + s.right.z * side * lateral,
        rot: r() * Math.PI * 2,
        scale: 0.7 + r() * 1.2,
        tangent: s.tan,
        side
      })
    }
    return out
  }

  buildInstanced(geo, material, points, mapFn) {
    if (!points.length) return null
    const mesh = new THREE.InstancedMesh(geo, material, points.length)
    const dummy = new THREE.Object3D()
    points.forEach((p, i) => {
      mapFn(dummy, p, i)
      dummy.updateMatrix()
      mesh.setMatrixAt(i, dummy.matrix)
    })
    this.group.add(mesh)
    this.addDisposable(mesh)
    return mesh
  }

  buildProp(kind) {
    const t = this.terrain
    const baseCol = new THREE.Color(t.ground)
    const accent = new THREE.Color(t.accent)
    const rockMat = new THREE.MeshLambertMaterial({ color: baseCol.clone().multiplyScalar(0.75), flatShading: true })
    const darkMat = new THREE.MeshLambertMaterial({ color: baseCol.clone().multiplyScalar(0.35), flatShading: true })
    const metalMat = new THREE.MeshLambertMaterial({ color: '#2b2927', flatShading: true })
    const boneMat = new THREE.MeshLambertMaterial({ color: '#bdb198', flatShading: true })
    const acMat = new THREE.MeshBasicMaterial({ color: accent })
    const pts = this.propPositions(kind === 'mountain' ? 14 : 34, kind === 'mountain' ? 40 : 17, kind === 'mountain' ? 100 : 62)

    if (kind === 'rock') {
      this.buildInstanced(new THREE.DodecahedronGeometry(1, 0), rockMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 0.6, p.z)
        d.rotation.set(p.rot, p.rot * 1.4, p.rot * 0.4)
        d.scale.set(p.scale * 2.2, p.scale * 1.5, p.scale * 2)
      })
    } else if (kind === 'mountain') {
      this.buildInstanced(new THREE.ConeGeometry(1, 1, 5), rockMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 5, p.z)
        d.scale.set(p.scale * 18, p.scale * 18, p.scale * 18)
        d.rotation.y = p.rot
      })
    } else if (kind === 'dune') {
      this.buildInstanced(new THREE.SphereGeometry(1, 7, 5), new THREE.MeshLambertMaterial({ color: baseCol.clone().multiplyScalar(1.15) }), pts, (d, p) => {
        d.position.set(p.x, p.y - p.scale * 0.7, p.z)
        d.scale.set(p.scale * 9, p.scale * 2.5, p.scale * 7)
      })
    } else if (kind === 'pine') {
      this.buildInstanced(new THREE.CylinderGeometry(0.28, 0.38, 4, 5), darkMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 2, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
      this.buildInstanced(new THREE.ConeGeometry(2.4, 7, 6), new THREE.MeshLambertMaterial({ color: new THREE.Color(t.ground).multiplyScalar(0.6), flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 5.4, p.z); d.scale.set(p.scale * 1.3, p.scale * 1.6, p.scale * 1.3); d.rotation.y = p.rot
      })
    } else if (kind === 'tree' || kind === 'palm') {
      this.buildInstanced(new THREE.CylinderGeometry(0.35, 0.55, 6, 5), darkMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 3, p.z); d.scale.setScalar(p.scale); d.rotation.z = (p.rot - 3.14) * 0.03
      })
      const crownCol = new THREE.Color(t.ground).multiplyScalar(0.72).lerp(new THREE.Color(t.accent), 0.18)
      this.buildInstanced(new THREE.IcosahedronGeometry(2.4, 0), new THREE.MeshLambertMaterial({ color: crownCol, flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 6.4, p.z)
        d.scale.set(p.scale * 1.5, p.scale * (kind === 'palm' ? 0.55 : 1.2), p.scale * 1.5)
        d.rotation.y = p.rot
      })
    } else if (kind === 'cactus') {
      this.buildInstanced(new THREE.CylinderGeometry(0.45, 0.55, 4.5, 6), new THREE.MeshLambertMaterial({ color: '#4c6138', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 2.2, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
    } else if (kind === 'fern') {
      this.buildInstanced(new THREE.ConeGeometry(1.7, 3.2, 5), new THREE.MeshLambertMaterial({ color: '#305a2f', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 1.2, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
    } else if (kind === 'wreck' || kind === 'rubble' || kind === 'cart') {
      this.buildInstanced(new THREE.BoxGeometry(2.2, 0.9, 4.6), new THREE.MeshLambertMaterial({ color: '#4c3a30', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + 0.55, p.z); d.rotation.set((p.rot - 3) * 0.05, p.rot, (p.rot - 3) * 0.03); d.scale.setScalar(p.scale)
      })
      this.buildInstanced(new THREE.BoxGeometry(1.8, 0.7, 1.8), darkMat, pts, (d, p) => {
        d.position.set(p.x, p.y + 1.22, p.z - 0.55 * Math.cos(p.rot)); d.rotation.y = p.rot; d.scale.setScalar(p.scale)
      })
    } else if (kind === 'tower') {
      this.buildInstanced(new THREE.BoxGeometry(6, 16, 6), new THREE.MeshLambertMaterial({ color: baseCol.clone().multiplyScalar(0.5), flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 8, p.z); d.scale.set(p.scale * 1.4, p.scale * (1.5 + p.rot), p.scale * 1.4); d.rotation.y = p.rot * 0.1
      })
      const neonPts = pts.filter((_, i) => i % 3 === 0)
      this.buildInstanced(new THREE.BoxGeometry(0.16, 2.2, 0.16), acMat, neonPts, (d, p) => {
        d.position.set(p.x + p.side * 3.2, p.y + p.scale * 12, p.z); d.scale.set(1, p.scale * 2, 1)
      })
    } else if (kind === 'house') {
      this.buildInstanced(new THREE.BoxGeometry(7, 5, 6), new THREE.MeshLambertMaterial({ color: baseCol.clone().multiplyScalar(1.25), flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 2.5, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
      this.buildInstanced(new THREE.ConeGeometry(5.1, 3, 4), darkMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 5.8, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot + Math.PI / 4
      })
    } else if (kind === 'bunker') {
      this.buildInstanced(new THREE.BoxGeometry(8, 3.2, 5), new THREE.MeshLambertMaterial({ color: '#514d42', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + 1.6, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
      this.buildInstanced(new THREE.BoxGeometry(1.4, 1.6, 0.2), metalMat, pts.filter((_, i) => i % 4 === 0), (d, p) => {
        d.position.set(p.x, p.y + 1.6, p.z); d.rotation.y = p.rot
      })
    } else if (kind === 'pylon') {
      this.buildInstanced(new THREE.CylinderGeometry(0.32, 0.5, 10, 4), metalMat, pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 5, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
      this.buildInstanced(new THREE.BoxGeometry(0.12, 0.12, 10), darkMat, pts.filter((_, i) => i % 2 === 0), (d, p) => {
        d.position.set(p.x, p.y + p.scale * 8, p.z); d.rotation.y = p.rot
      })
    } else if (kind === 'bones') {
      this.buildInstanced(new THREE.DodecahedronGeometry(0.7, 0), boneMat, pts, (d, p) => {
        d.position.set(p.x, p.y + 0.35, p.z); d.scale.set(p.scale, p.scale * 0.8, p.scale * 1.15); d.rotation.set(p.rot, p.rot, p.rot)
      })
      this.buildInstanced(new THREE.CylinderGeometry(0.18, 0.18, 5, 5), boneMat, pts.slice(0, 20), (d, p) => {
        d.position.set(p.x + 1.5, p.y + 0.2, p.z); d.rotation.set(Math.PI / 2, p.rot, 0)
      })
    } else if (kind === 'ice') {
      this.buildInstanced(new THREE.ConeGeometry(1.6, 6, 5), new THREE.MeshLambertMaterial({ color: '#bfe9f2', flatShading: true, transparent: true, opacity: 0.9 }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 2, p.z); d.scale.set(p.scale, p.scale * 2.5, p.scale); d.rotation.y = p.rot
      })
    } else if (kind === 'lava') {
      const lavaMat = new THREE.MeshBasicMaterial({ color: '#ff6a24' })
      this.buildInstanced(new THREE.CircleGeometry(1, 10), lavaMat, pts.slice(0, 22), (d, p) => {
        d.position.set(p.x, p.y + 0.08, p.z); d.rotation.x = -Math.PI / 2; d.scale.set(p.scale * 4, p.scale * 2.4, 1)
      })
      this.buildInstanced(new THREE.ConeGeometry(1, 1, 5), new THREE.MeshLambertMaterial({ color: '#2b1b1a', emissive: '#5c1c0e', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 2.5, p.z); d.scale.set(p.scale * 2, p.scale * 5, p.scale * 2); d.rotation.y = p.rot
      })
    } else if (kind === 'sign') {
      this.buildInstanced(new THREE.BoxGeometry(0.22, 5, 0.22), metalMat, pts.filter((_, i) => i % 3 === 0), (d, p) => {
        d.position.set(p.x, p.y + 2.5, p.z); d.scale.setScalar(p.scale)
      })
      this.buildInstanced(new THREE.BoxGeometry(4.5, 2, 0.18), acMat, pts.filter((_, i) => i % 3 === 0), (d, p) => {
        d.position.set(p.x, p.y + 4.2, p.z); d.rotation.y = p.rot; d.scale.setScalar(p.scale)
      })
    } else if (kind === 'mine') {
      this.buildInstanced(new THREE.BoxGeometry(7, 6, 5), metalMat, pts, (d, p) => {
        d.position.set(p.x, p.y + 3, p.z); d.rotation.y = p.rot; d.scale.setScalar(p.scale)
      })
      this.buildInstanced(new THREE.BoxGeometry(2.8, 3.2, 0.3), new THREE.MeshBasicMaterial({ color: '#0a0807' }), pts, (d, p) => {
        d.position.set(p.x, p.y + 1.6, p.z); d.rotation.y = p.rot
      })
    } else if (kind === 'idol') {
      this.buildInstanced(new THREE.CylinderGeometry(1.4, 1.8, 9, 4), new THREE.MeshLambertMaterial({ color: '#55503c', flatShading: true }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 4.5, p.z); d.scale.setScalar(p.scale); d.rotation.y = p.rot
      })
      this.buildInstanced(new THREE.SphereGeometry(1.3, 6, 5), new THREE.MeshBasicMaterial({ color: accent }), pts, (d, p) => {
        d.position.set(p.x, p.y + p.scale * 9.2, p.z); d.scale.setScalar(p.scale)
      })
    } else if (kind === 'wire') {
      this.buildInstanced(new THREE.CylinderGeometry(0.12, 0.12, 3, 4), metalMat, pts, (d, p) => {
        d.position.set(p.x, p.y + 1.5, p.z); d.scale.setScalar(p.scale)
      })
    } else if (kind === 'crater') {
      this.buildInstanced(new THREE.CircleGeometry(1, 10), new THREE.MeshLambertMaterial({ color: '#211c19' }), pts, (d, p) => {
        d.position.set(p.x, p.y + 0.05, p.z); d.rotation.x = -Math.PI / 2; d.scale.set(p.scale * 4, p.scale * 3, 1)
      })
    }
  }

  buildWeather() {
    const w = this.weather.id
    const r = this.rand
    this.precip = null
    this.tornado = null
    this.water = null
    this.quicksand = null
    this.flash = 0
    this.nextStrike = 6

    if (w === 'acid' || w === 'storm' || w === 'hurricane') {
      const count = this.quality === 'low' ? 600 : 1300
      const arr = new Float32Array(count * 3)
      for (let i = 0; i < count; i++) {
        arr[i * 3] = (r() - 0.5) * 100
        arr[i * 3 + 1] = r() * 45
        arr[i * 3 + 2] = (r() - 0.5) * 100
      }
      const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(arr, 3))
      const col = w === 'acid' ? '#8fdc5a' : w === 'storm' ? '#a8bfd8' : '#93b9c2'
      this.rain = new THREE.Points(geo, new THREE.PointsMaterial({ color: col, size: 0.12, transparent: true, opacity: 0.55, depthWrite: false }))
      this.rain.frustumCulled = false
      this.group.add(this.rain)
      this.addDisposable(this.rain)
      this.rainCount = count
    }

    if (w === 'twister') {
      this.tornado = this.makeTornado()
      this.group.add(this.tornado)
    }

    if (w === 'flood') {
      const waterMat = new THREE.MeshBasicMaterial({ color: '#2d4540', transparent: true, opacity: 0.5, depthWrite: false })
      const water = new THREE.Mesh(new THREE.PlaneGeometry(420, 420), waterMat)
      water.rotation.x = -Math.PI / 2
      water.position.y = -0.18
      this.group.add(water)
      this.water = water
      this.addDisposable(water)
    }

    if (w === 'quicksand') {
      const c = document.createElement('canvas'); c.width = c.height = 128
      const x = c.getContext('2d')
      x.fillStyle = '#5a4325'; x.fillRect(0, 0, 128, 128)
      for (let i = 0; i < 48; i++) {
        x.fillStyle = `rgba(${90 + r() * 60},${65 + r() * 40},${25 + r() * 30},0.5)`
        x.beginPath(); x.arc(r() * 128, r() * 128, 3 + r() * 14, 0, 7); x.fill()
      }
      const tex = new THREE.CanvasTexture(c)
      const mat = new THREE.MeshLambertMaterial({ map: tex, color: '#c0a06a' })
      const q = new THREE.Mesh(new THREE.PlaneGeometry(420, 420), mat)
      q.rotation.x = -Math.PI / 2; q.position.y = -0.55
      this.group.add(q); this.quicksand = q
      this.addDisposable(q)
    }

    if (w === 'clear' || w === 'cloudy') {
      // ash motes / heat shimmer
      const count = 160
      const arr = new Float32Array(count * 3)
      for (let i = 0; i < count; i++) { arr[i * 3] = (r() - 0.5) * 90; arr[i * 3 + 1] = r() * 20; arr[i * 3 + 2] = (r() - 0.5) * 90 }
      const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(arr, 3))
      this.ash = new THREE.Points(geo, new THREE.PointsMaterial({ color: w === 'clear' ? '#e6b27c' : '#9c948c', size: 0.1, transparent: true, opacity: 0.4, depthWrite: false }))
      this.group.add(this.ash); this.addDisposable(this.ash)
    }

    // lightning flash light
    this.strikeLight = new THREE.PointLight(0xcfe4ff, 0, 120)
    this.strikeLight.position.set(0, 30, 0)
    this.group.add(this.strikeLight)
    this.boltMat = new THREE.LineBasicMaterial({ color: 0xe6f0ff, transparent: true, opacity: 0 })
    this.bolt = new THREE.Line(new THREE.BufferGeometry(), this.boltMat)
    this.bolt.frustumCulled = false
    this.group.add(this.bolt)

    // wet sheen for rain weathers
    if (w === 'acid' || w === 'storm' || w === 'hurricane' || w === 'flood') {
      this.road.material.color = new THREE.Color('#a8b2ac')
    }
  }

  makeTornado() {
    const g = new THREE.Group()
    const mat = new THREE.MeshBasicMaterial({ color: '#8c7b65', transparent: true, opacity: 0.2, side: THREE.DoubleSide, depthWrite: false })
    const rings = []
    for (let i = 0; i < 7; i++) {
      const ring = new THREE.Mesh(new THREE.CylinderGeometry(1.2 + i * 1.4, 2.4 + i * 2.3, 7, 16, 1, true), mat)
      ring.position.y = 3 + i * 5
      ring.userData.spin = 0.7 + Math.random() * 0.8
      g.add(ring); rings.push(ring)
    }
    const s = this.samples[Math.floor(this.samples.length * 0.68)]
    const side = this.rand() > 0.5 ? 1 : -1
    g.position.set(s.p.x + s.right.x * side * 38, s.p.y - 1, s.p.z + s.right.z * side * 38)
    g.userData.rings = rings
    g.userData.radius = 20
    return g
  }

  nearest(pos, hint = 0, window = 46) {
    let best = -1, bestD = Infinity
    const start = hint - window, end = hint + window
    for (let k = start; k <= end; k++) {
      const i = ((k % N_SAMPLES) + N_SAMPLES) % N_SAMPLES
      const s = this.samples[i]
      const dx = pos.x - s.p.x, dz = pos.z - s.p.z
      const d = dx * dx + dz * dz
      if (d < bestD) { bestD = d; best = i }
    }
    if (bestD > 900) {
      for (let i = 0; i < N_SAMPLES; i += 8) {
        const s = this.samples[i]
        const dx = pos.x - s.p.x, dz = pos.z - s.p.z
        const d = dx * dx + dz * dz
        if (d < bestD) { bestD = d; best = i }
      }
    }
    const s = this.samples[best]
    const dx = pos.x - s.p.x, dz = pos.z - s.p.z
    const lateral = dx * s.right.x + dz * s.right.z
    return { index: best, distance: Math.sqrt(bestD), lateral, sample: s }
  }

  sampleAt(index) {
    return this.samples[((index % N_SAMPLES) + N_SAMPLES) % N_SAMPLES]
  }

  worldAt(index, lateral = 0, yOff = 0) {
    const s = this.sampleAt(index)
    return new THREE.Vector3(s.p.x + s.right.x * lateral, s.p.y + yOff, s.p.z + s.right.z * lateral)
  }

  startPose(slot = 0) {
    // grid behind the start line, staggered rows
    const row = Math.floor(slot / 2)
    const col = slot % 2
    const index = 18 + row * 13
    const s = this.sampleAt(index)
    const lateral = (col === 0 ? -1 : 1) * 3.6
    return {
      pos: new THREE.Vector3(s.p.x + s.right.x * lateral, s.p.y + 0.02, s.p.z + s.right.z * lateral),
      yaw: Math.atan2(s.tan.x, s.tan.z),
      index,
      lateral
    }
  }

  applyToScene(scene) {
    scene.add(this.group)
    scene.background = this.skyColor.clone().lerp(new THREE.Color(this.weather.tint), 0.08)
    const fogDensity = 0.0048 * this.weather.fog
    scene.fog = new THREE.FogExp2(this.fogColor.getHex(), fogDensity)
  }

  update(dt, cameraPos = null) {
    this.t += dt
    const w = this.weather.id
    if (this.rain) {
      const p = this.rain.geometry.attributes.position.array
      const wind = this.weather.wind
      const speed = w === 'hurricane' ? 36 : 22
      for (let i = 0; i < this.rainCount; i++) {
        p[i * 3 + 1] -= speed * dt
        p[i * 3] += (2.2 + wind * 5) * dt
        p[i * 3 + 2] += wind * 1.4 * dt
        if (p[i * 3 + 1] < -2) {
          p[i * 3 + 1] = 40
          p[i * 3] = (Math.random() - 0.5) * 110
          p[i * 3 + 2] = (Math.random() - 0.5) * 110
        }
      }
      this.rain.geometry.attributes.position.needsUpdate = true
      this.rain.position.x = cameraPos ? cameraPos.x * 0.35 : 0
      this.rain.position.z = cameraPos ? cameraPos.z * 0.35 : 0
    }
    if (this.ash) {
      const p = this.ash.geometry.attributes.position.array
      for (let i = 0; i < 160; i++) {
        p[i * 3 + 1] += (0.4 + i % 3 * 0.3) * dt
        p[i * 3] += Math.sin(this.t + i) * 0.08 * dt
        if (p[i * 3 + 1] > 20) p[i * 3 + 1] = 0
      }
      this.ash.geometry.attributes.position.needsUpdate = true
    }
    if (this.tornado) {
      for (const ring of this.tornado.userData.rings) ring.rotation.y += ring.userData.spin * dt
      this.tornado.rotation.y += 0.08 * dt
    }
    if (this.water) {
      this.water.material.opacity = 0.42 + Math.sin(this.t * 1.2) * 0.06
    }
    if (this.sun) this.sun.position.y = 90 + Math.sin(this.t * 0.1) * 2
    // lightning
    if (w === 'storm' || w === 'acid' || w === 'hurricane') {
      this.nextStrike -= dt
      if (this.flash > 0) {
        this.flash = Math.max(0, this.flash - dt * 2.8)
        this.boltMat.opacity = this.flash
        this.strikeLight.intensity = this.flash * 14
        this.hemi.intensity = 0.9 + this.flash * 1.6
      } else {
        this.boltMat.opacity = 0
        this.strikeLight.intensity = 0
        this.hemi.intensity = 0.9
      }
      if (this.nextStrike <= 0) {
        this.nextStrike = 5 + Math.random() * 7
        this.triggerLightning(cameraPos)
      }
    }
  }

  triggerLightning(near = null) {
    let x = near?.x ?? 0, z = near?.z ?? 0
    x += (Math.random() - 0.5) * 50
    z += (Math.random() - 0.5) * 50
    const pts = [new THREE.Vector3(x, 45, z)]
    let px = x, py = 45, pz = z
    for (let i = 0; i < 8; i++) {
      px += (Math.random() - 0.5) * 5
      py -= 4 + Math.random() * 2.5
      pz += (Math.random() - 0.5) * 3
      pts.push(new THREE.Vector3(px, py, pz))
    }
    this.bolt.geometry.dispose()
    this.bolt.geometry = new THREE.BufferGeometry().setFromPoints(pts)
    this.flash = 1
    this.strikeLight.position.set(x, 25, z)
    this.lastStrike = { x, z }
    return { x, z }
  }

  addDisposable(obj) {
    if (!this._disposables) this._disposables = []
    this._disposables.push(obj)
  }

  dispose() {
    this.group.traverse(o => {
      if (o.isMesh || o.isPoints || o.isLine) {
        o.geometry?.dispose?.()
        const mats = Array.isArray(o.material) ? o.material : [o.material]
        for (const m of mats) {
          if (!m) continue
          if (m.map) m.map.dispose?.()
          m.dispose?.()
        }
      }
    })
    this.group.removeFromParent()
  }
}

export { N_SAMPLES }

import * as THREE from 'three'
