              </button>
              <button class="menu-btn" data-action="career">
                <span class="mn">04</span><span class="mt"><b>CAREER</b><em>8 underbosses · 3 demigods</em></span><span class="ma">▶</span>
              </button>
              <button class="menu-btn" data-action="garage">
