      <p class="panel-hint">RESTART re-runs this heat. Quitting abandons the contract and any unclaimed bounty.</p>`, 'pause-modal')
    $('[data-action="resume"]', this.modals).addEventListener('click', () => {
      this.closeModal()
      this.race?.resume()
    })
