h1, h2, h3, h4, p { margin: 0; }
::selection { background: var(--blood-bright); color: #fff; }

::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-track { background: #0a0909; }
::-webkit-scrollbar-thumb { background: #3a312c; border: 2px solid #0a0909; }
::-webkit-scrollbar-thumb:hover { background: var(--rust); }

/* ---------------------------------------------------------------- splash -- */
#boot-splash {
  position: fixed; inset: 0; z-index: 200;
  display: grid; place-content: center; justify-items: center; gap: 18px;
  background: radial-gradient(circle at 50% 40%, #1c1010, #050404 70%);
  transition: opacity 0.8s ease, visibility 0.8s;
}
#boot-splash.done { opacity: 0; visibility: hidden; }
.boot-skull { font-size: 54px; color: var(--blood-bright); text-shadow: 0 0 30px rgba(221, 43, 36, 0.5); animation: pulse 1.8s infinite; }
.boot-title { font-family: var(--display); font-size: clamp(48px, 12vw, 92px); letter-spacing: 0.14em; color: var(--bone); line-height: 0.9; }
.boot-bar { width: 190px; height: 3px; background: #241c1a; overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 40%; background: linear-gradient(90deg, var(--blood), var(--amber)); animation: bootload 1.2s ease-in-out infinite; }
@keyframes bootload { 0% { transform: translateX(-120%); } 100% { transform: translateX(370%); } }
@keyframes pulse { 50% { opacity: 0.55; } }

/* ---------------------------------------------------------------- layers -- */
#menu-bg {
  position: fixed; inset: 0; width: 100%; height: 100%;
  z-index: 0; opacity: 0.9; pointer-events: none;
}
#decor { position: fixed; inset: 0; z-index: 1; pointer-events: none; overflow: hidden; }
#app { position: relative; z-index: 2; min-height: 100vh; min-height: 100dvh; }
#race-canvas {
  position: fixed; inset: 0; width: 100%; height: 100%;
  z-index: 10; display: none; background: #09090b;
}
body[data-screen='race'] #race-canvas { display: block; }
#race-ui {
  position: fixed; inset: 0; z-index: 12; display: none;
  pointer-events: none; font-family: var(--body);
}
body[data-screen='race'] #race-ui { display: block; }
#modals { position: relative; z-index: 60; }
#global-toast {
  position: fixed; left: 50%; bottom: calc(24px + var(--safe-bottom));
  z-index: 150; transform: translate(-50%, 30px); opacity: 0;
  pointer-events: none; max-width: min(90vw, 520px);
  padding: 11px 20px; background: rgba(10, 9, 9, 0.94);
  border: 1px solid var(--line); border-left: 3px solid var(--amber);
  font-family: var(--display); font-size: 19px; letter-spacing: 0.08em;
  text-align: center; transition: 0.3s ease; box-shadow: var(--shadow);
}
#global-toast.show { opacity: 1; transform: translate(-50%, 0); }
#global-toast.good { border-left-color: var(--acid); color: #dcf6bf; }
#global-toast.bad { border-left-color: var(--blood-bright); color: #ffd0c9; }

/* ---------------------------------------------------------------- decor --- */
.decor-layer { position: absolute; inset: 0; }
.decor-layer::after {
  content: ''; position: absolute; inset: 0;
  background:
    repeating-linear-gradient(0deg, transparent 0 2px, rgba(0, 0, 0, 0.16) 2px 3px),
    radial-gradient(90% 80% at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.65) 100%);
  mix-blend-mode: multiply; opacity: 0.5;
}
.chain { position: absolute; top: -40px; height: 115%; color: #4a3a30; opacity: 0.5; filter: drop-shadow(0 4px 6px rgba(0, 0, 0, 0.7)); }
.chain-left { left: max(-26px, calc(var(--safe-left) - 26px)); width: 66px; transform: rotate(-4deg); }
.chain-right { right: max(-26px, calc(var(--safe-right) - 26px)); width: 66px; transform: rotate(5deg); }
.chain-svg { width: 100%; height: 100%; }
.blood-splash {
  position: absolute; border-radius: 50% 44% 55% 48%;
  background:
    radial-gradient(circle at 34% 30%, rgba(126, 14, 18, 0.65), transparent 46%),
    radial-gradient(circle at 65% 62%, #6d0c10, #330507 74%);
  filter: blur(0.4px) saturate(1.2); opacity: 0.42;
  box-shadow: 0 0 60px rgba(70, 5, 8, 0.45);
}
.blood-1 { width: 340px; height: 300px; left: -130px; bottom: -80px; transform: rotate(12deg); }
.blood-2 { width: 240px; height: 300px; right: -90px; top: 22%; transform: rotate(-15deg); opacity: 0.3; }
.blood-3 { width: 130px; height: 90px; right: 10%; bottom: 6%; transform: rotate(22deg); opacity: 0.28; }
.bone-pile { position: absolute; left: 2%; bottom: -8px; width: min(270px, 22vw); color: #b9a98c; opacity: 0.3; }
.hanging-hook { position: absolute; right: 6%; top: 0; width: 65px; color: #5d4a3c; opacity: 0.55; }
.ember-field { position: absolute; inset: 0; }
.ember-field i {
  position: absolute; bottom: -10px; width: 3px; height: 3px; border-radius: 50%;
  background: var(--amber); box-shadow: 0 0 8px var(--amber);
  animation: ember 9s linear infinite;
}
.ember-field i:nth-child(1) { left: 8%; animation-delay: 0s; }
.ember-field i:nth-child(2) { left: 18%; animation-delay: 2.2s; animation-duration: 11s; }
.ember-field i:nth-child(3) { left: 31%; animation-delay: 4s; }
.ember-field i:nth-child(4) { left: 44%; animation-delay: 1s; animation-duration: 13s; }
.ember-field i:nth-child(5) { left: 55%; animation-delay: 5.4s; }
.ember-field i:nth-child(6) { left: 66%; animation-delay: 3.1s; animation-duration: 10s; }
.ember-field i:nth-child(7) { left: 74%; animation-delay: 6.4s; }
.ember-field i:nth-child(8) { left: 83%; animation-delay: 0.7s; animation-duration: 12s; }
.ember-field i:nth-child(9) { left: 91%; animation-delay: 4.8s; }
.ember-field i:nth-child(10) { left: 97%; animation-delay: 2.8s; }
@keyframes ember {
  0% { transform: translateY(0) scale(1); opacity: 0; }
  12% { opacity: 1; }
  100% { transform: translateY(-95vh) translateX(30px) scale(0.3); opacity: 0; }
}
@media (max-width: 700px) {
  .chain { width: 40px; opacity: 0.3; }
  .bone-pile { width: 140px; opacity: 0.2; }
  .hanging-hook { display: none; }
}

/* --------------------------------------------------------------- shared --- */
.screen {
  position: relative; min-height: 100dvh;
  display: flex; flex-direction: column;
  padding: calc(18px + var(--safe-top)) max(18px, var(--safe-right)) calc(12px + var(--safe-bottom)) max(18px, var(--safe-left));
}
.screen-inner { width: 100%; max-width: 1420px; margin: 0 auto; flex: 1; }
.screen-foot {
  width: 100%; max-width: 1420px; margin: 20px auto 0;
  display: flex; justify-content: space-between; gap: 14px; flex-wrap: wrap;
  padding-top: 12px; border-top: 1px solid var(--line-soft);
  font-family: var(--type); font-size: 10px; letter-spacing: 0.12em;
  color: rgba(149, 139, 128, 0.7); text-transform: uppercase;
}
.screen-foot span:nth-child(2) { text-align: center; }

.kicker {
  display: inline-block; font-family: var(--type); font-size: 10px;
  letter-spacing: 0.28em; text-transform: uppercase; color: var(--amber);
}
.danger-text { color: var(--blood-bright) !important; }
.muted { color: var(--muted); }
.hint, .panel-hint {
  margin-top: 14px; font-family: var(--type); font-size: 10px;
  letter-spacing: 0.09em; color: var(--muted); text-transform: uppercase;
}

.panel {
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.035), transparent 34%),
    linear-gradient(180deg, rgba(23, 20, 21, 0.97), rgba(13, 11, 12, 0.98));
  border: 1px solid var(--line);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  position: relative;
}
.panel::before {
  content: ''; position: absolute; inset: 5px; pointer-events: none;
  border: 1px solid rgba(232, 225, 210, 0.045);
}
.panel-head {
  display: flex; justify-content: space-between; align-items: flex-start; gap: 14px;
  padding-bottom: 14px; margin-bottom: 16px; border-bottom: 1px solid var(--line);
}
.panel-head h2, .panel-head h3 { font-family: var(--display); font-size: 30px; font-weight: 400; letter-spacing: 0.04em; line-height: 1; }
.panel-kicker {
  display: flex; justify-content: space-between; align-items: center; gap: 10px;
  padding-bottom: 10px; margin-bottom: 14px; border-bottom: 1px solid var(--line-soft);
  font-family: var(--type); font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--muted);
}
.panel-kicker b { color: var(--amber); }
.panel-foot {
  display: flex; justify-content: space-between; gap: 10px; margin-top: 12px;
  font-family: var(--type); font-size: 9px; letter-spacing: 0.12em; color: var(--muted); text-transform: uppercase;
}
.record-count {
  font-family: var(--type); font-size: 9px; letter-spacing: 0.12em;
  color: var(--amber); border: 1px solid rgba(237, 164, 60, 0.3);
  padding: 5px 9px; text-transform: uppercase; white-space: nowrap;
}

/* -------------------------------------------------------------- buttons --- */
.btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  padding: 13px 22px; min-height: 46px;
  border: 1px solid var(--line); background: #1a1617; color: var(--bone);
  font-family: var(--display); font-size: 20px; letter-spacing: 0.09em;
  text-transform: uppercase; cursor: pointer; overflow: hidden;
  transition: transform 0.12s, background 0.18s, border-color 0.18s, box-shadow 0.18s;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}
.btn::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(120deg, transparent 30%, rgba(255, 255, 255, 0.14) 48%, transparent 62%);
  transform: translateX(-120%); transition: transform 0.5s ease;
}
.btn:hover::after { transform: translateX(120%); }
.btn:active { transform: translateY(1px) scale(0.995); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; filter: grayscale(0.6); }
.btn-primary {
  background: linear-gradient(180deg, #c4531f, #922f12);
  border-color: #e06a2c; color: #fff4e8;
  box-shadow: 0 8px 24px rgba(179, 68, 31, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2);
}
.btn-primary:hover { background: linear-gradient(180deg, #db6227, #a83a17); }
.btn-danger {
  background: linear-gradient(180deg, #a51d1f, #6c0e12);
  border-color: #d43633; color: #ffe9e5;
  box-shadow: 0 8px 24px rgba(141, 19, 24, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.15);
}
.btn-danger:hover { background: linear-gradient(180deg, #bf2527, #7f1115); }
.btn-ghost { background: rgba(255, 255, 255, 0.025); }
.btn-ghost:hover { background: rgba(255, 255, 255, 0.07); border-color: rgba(232, 225, 210, 0.3); }
.btn-large { min-height: 56px; font-size: 24px; padding: 14px 30px; }
.btn-small { min-height: 34px; padding: 6px 13px; font-size: 15px; letter-spacing: 0.07em; }
.btn-block { display: flex; width: 100%; }

.link-btn {
  background: none; border: 0; padding: 2px 0; cursor: pointer;
  font-family: var(--type); font-size: 10px; letter-spacing: 0.16em;
  color: var(--muted); text-transform: uppercase; border-bottom: 1px solid transparent;
}
.link-btn:hover { color: var(--amber); border-bottom-color: var(--amber); }

.icon-btn {
  display: inline-grid; place-items: center; width: 40px; height: 40px;
  background: rgba(255, 255, 255, 0.03); border: 1px solid var(--line);
  color: var(--bone-dim); cursor: pointer; font-size: 16px; transition: 0.18s;
}
.icon-btn:hover { border-color: var(--amber); color: var(--amber); background: rgba(237, 164, 60, 0.08); }
.icon-btn.small { width: 30px; height: 30px; font-size: 12px; }

/* --------------------------------------------------------------- brand ---- */
.brand { position: relative; user-select: none; }
.brand-kicker {
  display: flex; align-items: center; gap: 12px;
  font-family: var(--type); font-size: 9px; letter-spacing: 0.34em;
  color: var(--amber-dim); text-transform: uppercase; margin-bottom: 8px;
}
.brand-kicker span { display: block; width: 34px; height: 1px; background: var(--amber-dim); }
.brand-kicker span:last-child { flex: 1; max-width: 90px; }
.brand-title {
  font-family: var(--display); font-weight: 400; line-height: 0.78;
  font-size: clamp(64px, 11vw, 148px); letter-spacing: 0.015em;
  display: flex; align-items: baseline; filter: drop-shadow(0 8px 26px rgba(0, 0, 0, 0.8));
}
.brand-hell { color: var(--bone); }
.brand-ride {
  color: transparent; -webkit-text-stroke: 2px var(--rust); text-stroke: 2px var(--rust);
  margin-left: 0.03em;
}
.brand-sub {
  display: flex; align-items: center; gap: 14px; margin-top: 12px;
  font-family: var(--display); font-size: clamp(14px, 1.6vw, 21px);
  letter-spacing: 0.52em; color: var(--amber);
}
.brand-sub span { padding-left: 0.52em; }
.brand-slash { width: 26px; height: 1px; background: var(--rust); }
.brand-slash:last-child { flex: 1; max-width: 120px; }
.brand-tag {
  margin-top: 9px; font-family: var(--type); font-size: 9px;
  letter-spacing: 0.26em; color: var(--muted); text-transform: uppercase;
}
.brand.compact .brand-title { font-size: clamp(40px, 5vw, 64px); }
.brand.compact .brand-sub { font-size: 12px; }

input.command:
cd /home/runner/work/PlayGround/PlayGround && cat >> src/styles.css <<'EOF'

/* --------------------------------------------------------------- login ---- */
.login-grid {
  display: grid; grid-template-columns: 1.15fr 0.85fr;
  gap: clamp(24px, 5vw, 76px); align-items: center;
  padding: clamp(16px, 3vw, 46px) 0;
}
.login-copy { display: flex; flex-direction: column; gap: 22px; }
.login-lede {
  max-width: 560px; color: var(--bone-dim); font-size: clamp(16px, 1.4vw, 20px);
  line-height: 1.55; border-left: 2px solid var(--blood); padding-left: 16px;
}
.world-stats {
  display: grid; grid-template-columns: repeat(4, auto); gap: 22px;
  max-width: 600px; padding: 18px 0; border-top: 1px solid var(--line-soft); border-bottom: 1px solid var(--line-soft);
}
.world-stats div { display: flex; flex-direction: column; gap: 3px; }
.world-stats b { font-family: var(--display); font-size: 36px; line-height: 0.9; color: var(--amber); }
.world-stats span { font-family: var(--type); font-size: 8px; letter-spacing: 0.13em; color: var(--muted); }
.login-badges { display: flex; flex-wrap: wrap; gap: 8px; }
.login-badges span {
  font-family: var(--type); font-size: 9px; letter-spacing: 0.1em; color: var(--bone-dim);
  border: 1px solid var(--line); padding: 6px 10px; background: rgba(255, 255, 255, 0.02);
}
.login-links { display: flex; gap: 22px; }
.login-panel { padding: clamp(18px, 2.4vw, 30px); }
.profile-list { display: flex; flex-direction: column; gap: 9px; margin-bottom: 16px; max-height: 42vh; overflow-y: auto; }
.profile-row { display: flex; gap: 8px; align-items: stretch; }
.profile-card {
  flex: 1; display: flex; align-items: center; gap: 13px; text-align: left;
  padding: 9px; background: rgba(255, 255, 255, 0.025); border: 1px solid var(--line);
  cursor: pointer; transition: 0.18s; min-width: 0;
}
.profile-card:hover { border-color: var(--amber); background: rgba(237, 164, 60, 0.06); transform: translateX(3px); }
.profile-avatar { width: 56px; height: 56px; background: #221819; border: 1px solid var(--line); flex-shrink: 0; }
.profile-copy { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.profile-copy b { font-family: var(--display); font-size: 23px; letter-spacing: 0.04em; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.profile-copy span { font-family: var(--type); font-size: 9px; letter-spacing: 0.08em; color: var(--amber-dim); }
.profile-copy em { font-style: normal; font-size: 11px; color: var(--muted); }
.profile-enter { font-family: var(--display); font-size: 13px; letter-spacing: 0.1em; color: var(--amber); opacity: 0; transition: 0.18s; white-space: nowrap; }
.profile-card:hover .profile-enter { opacity: 1; }
.profile-del {
  width: 34px; border: 1px solid var(--line); background: transparent; color: var(--muted);
  cursor: pointer; font-size: 13px; transition: 0.18s;
}
.profile-del:hover { color: #fff; background: var(--blood); border-color: var(--blood-bright); }
.empty-profiles {
  display: flex; flex-direction: column; align-items: center; gap: 8px; text-align: center;
  padding: 26px 14px 30px; border: 1px dashed rgba(232, 225, 210, 0.18); margin-bottom: 16px;
}
.empty-skull { width: 58px; color: #54463c; }
.empty-skull svg { width: 100%; }
.empty-profiles b { font-family: var(--display); font-size: 24px; letter-spacing: 0.08em; }
.empty-profiles p { color: var(--muted); font-size: 14px; max-width: 260px; }
.portrait-frame {
  position: relative; overflow: hidden; background: #211516; border: 1px solid var(--line);
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.8);
}
.portrait-frame canvas { width: 100%; height: 100%; object-fit: cover; }
.portrait-frame.big { aspect-ratio: 1; }
.scanlines {
  position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0, 0, 0, 0.22) 3px 4px);
  mix-blend-mode: multiply;
}
.portrait-stamp {
  position: absolute; left: 0; bottom: 0; padding: 4px 12px;
  background: var(--blood); color: #ffe9e4;
  font-family: var(--type); font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase;
}

/* -------------------------------------------------------------- create ---- */
.create-grid {
  display: grid; grid-template-columns: minmax(280px, 0.72fr) 1.28fr;
  gap: clamp(16px, 2.4vw, 32px); align-items: start; padding: 12px 0;
}
.create-preview { padding: 18px; position: sticky; top: calc(14px + var(--safe-top)); }
.preview-kicker { font-family: var(--type); font-size: 9px; letter-spacing: 0.18em; color: var(--amber); margin-bottom: 10px; }
.preview-id { display: flex; flex-direction: column; gap: 2px; padding: 12px 0 8px; }
.preview-id b { font-family: var(--display); font-size: 34px; line-height: 1; letter-spacing: 0.03em; }
.preview-id span { font-family: var(--type); font-size: 9px; letter-spacing: 0.12em; color: var(--muted); }
.preview-bonus { font-size: 13px; color: var(--bone-dim); border-left: 2px solid var(--rust); padding-left: 9px; margin-bottom: 12px; }
.preview-bonus b { color: var(--amber); }
.preview-warning { margin-top: 10px; font-family: var(--type); font-size: 9px; color: #b37a6d; line-height: 1.5; }
.create-form { padding: clamp(16px, 2.4vw, 28px); }
.field { display: flex; flex-direction: column; gap: 7px; margin-bottom: 16px; }
.field label {
  font-family: var(--type); font-size: 9px; letter-spacing: 0.16em;
  color: var(--bone-dim); text-transform: uppercase; display: flex; justify-content: space-between; gap: 10px;
}
.field label span { color: var(--muted); font-size: 8px; letter-spacing: 0.08em; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 18px; }
.field.wide { grid-column: 1 / -1; }
.text-input {
  width: 100%; padding: 12px 15px; background: #0a0909; border: 1px solid var(--line);
  font-family: var(--display); font-size: 27px; letter-spacing: 0.1em; color: var(--bone);
  outline: none; transition: 0.18s; text-transform: uppercase;
}
.text-input::placeholder { color: #4b433d; }
.text-input:focus { border-color: var(--amber); box-shadow: 0 0 0 3px rgba(237, 164, 60, 0.1); }
.segmented { display: flex; gap: 6px; flex-wrap: wrap; }
.seg {
  flex: 1; min-width: 70px; padding: 9px 12px; border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.02); color: var(--muted); cursor: pointer;
  font-family: var(--display); font-size: 17px; letter-spacing: 0.06em; transition: 0.16s;
}
.seg:hover { color: var(--bone); border-color: rgba(232, 225, 210, 0.3); }
.seg.active { background: rgba(179, 68, 31, 0.22); border-color: var(--rust); color: #ffd9c2; }
.origin-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; }
.origin-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 3px; text-align: left;
  padding: 9px 11px; background: rgba(255, 255, 255, 0.02); border: 1px solid var(--line);
  cursor: pointer; transition: 0.16s; min-height: 76px;
}
.origin-card b { font-size: 18px; color: var(--amber-dim); line-height: 1; }
.origin-card span { font-family: var(--display); font-size: 16px; letter-spacing: 0.06em; }
.origin-card em { font-style: normal; font-size: 10px; line-height: 1.3; color: var(--muted); }
.origin-card:hover { border-color: rgba(237, 164, 60, 0.45); }
.origin-card.active { border-color: var(--amber); background: rgba(237, 164, 60, 0.1); box-shadow: inset 0 0 24px rgba(237, 164, 60, 0.08); }
.origin-card.active b { color: var(--amber); }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  padding: 6px 10px; background: rgba(255, 255, 255, 0.025); border: 1px solid var(--line);
  color: var(--muted); cursor: pointer; font-family: var(--body);
  font-size: 12px; letter-spacing: 0.04em; text-transform: uppercase; transition: 0.15s;
}
.chip:hover { color: var(--bone); border-color: rgba(232, 225, 210, 0.3); }
.chip.active { background: rgba(179, 68, 31, 0.25); border-color: var(--rust); color: #ffdcc7; }
.swatches { gap: 6px; }
.swatch {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 7px 4px 4px;
  background: rgba(255, 255, 255, 0.02); border: 1px solid var(--line);
  cursor: pointer; color: var(--muted); font-size: 10px; text-transform: uppercase; transition: 0.15s;
}
.swatch i { display: block; width: 18px; height: 18px; border: 1px solid rgba(0, 0, 0, 0.5); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12); }
.swatch:hover { border-color: rgba(232, 225, 210, 0.35); }
.swatch.active { border-color: var(--amber); color: var(--bone); background: rgba(237, 164, 60, 0.1); }
.swatch.simple { padding: 3px; }
