/* -------------------------------------------------------------- modals ---- */
.modal-backdrop {
  position: fixed; inset: 0; z-index: 60;
  display: flex; align-items: center; justify-content: center;
  padding: max(14px, var(--safe-top)) max(14px, var(--safe-right)) max(14px, var(--safe-bottom)) max(14px, var(--safe-left));
  background: rgba(4, 3, 3, 0.82); backdrop-filter: blur(6px);
  animation: fadeIn 0.22s ease;
}
.modal {
  position: relative; width: 100%; max-width: 620px; max-height: calc(100dvh - 28px);
  overflow-y: auto; padding: clamp(20px, 3vw, 34px);
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.05), transparent 32%),
    linear-gradient(180deg, #1a1516, #0d0b0c);
  border: 1px solid rgba(232, 225, 210, 0.2);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.8), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  animation: modalIn 0.28s cubic-bezier(0.2, 0.9, 0.3, 1);
}
.modal::before {
  content: ''; position: absolute; inset: 6px; pointer-events: none;
  border: 1px solid rgba(232, 225, 210, 0.06);
}
@keyframes fadeIn { from { opacity: 0; } }
@keyframes modalIn { from { opacity: 0; transform: translateY(22px) scale(0.97); } }
.modal h2 {
  font-family: var(--display); font-size: clamp(32px, 4.4vw, 48px); font-weight: 400;
  letter-spacing: 0.03em; line-height: 0.95; margin: 4px 0 10px;
}
.modal h3 { font-family: var(--display); font-size: 22px; font-weight: 400; letter-spacing: 0.05em; color: var(--amber); }
