.standings-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding-bottom: 8px; margin-bottom: 7px; border-bottom: 1px solid var(--line); }
.standings-head span { font-family: var(--type); font-size: 9px; letter-spacing: 0.14em; color: var(--bone-dim); }
