.boss-star { font-style: normal; color: var(--blood-bright); font-size: 11px; }
.result-actions { display: flex; gap: 8px; flex-wrap: wrap; padding: 0 clamp(18px, 2.6vw, 26px) clamp(18px, 2.6vw, 26px); }
