cd /home/runner/work/PlayGround/PlayGround && cat >> src/styles.css <<'EOF'

/* ================================================================ RACE HUD == */
.race-hud {
  position: absolute; inset: 0; pointer-events: none;
  color: var(--bone); user-select: none; overflow: hidden;
  padding: calc(10px + var(--safe-top)) calc(10px + var(--safe-right)) calc(10px + var(--safe-bottom)) calc(10px + var(--safe-left));
  font-family: var(--body);
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.85);
}
.race-hud button { pointer-events: auto; text-shadow: none; }

.rh-top {
  position: absolute; top: calc(10px + var(--safe-top));
  left: calc(10px + var(--safe-left)); right: calc(10px + var(--safe-right));
  display: flex; align-items: flex-start; gap: 7px;
}
.rh-block {
  display: flex; flex-direction: column; gap: 0; min-width: 62px;
  padding: 5px 9px; background: linear-gradient(180deg, rgba(10, 9, 9, 0.82), rgba(10, 9, 9, 0.55));
  border: 1px solid rgba(232, 225, 210, 0.14); border-top: 2px solid var(--rust);
  backdrop-filter: blur(4px);
}
.rh-block span { font-family: var(--type); font-size: 7px; letter-spacing: 0.16em; color: var(--muted); line-height: 1; }
.rh-block b { font-family: var(--display); font-size: 22px; letter-spacing: 0.03em; line-height: 1.1; }
.rh-pos b { color: var(--amber); }
.rh-mode { flex: 1; display: flex; flex-direction: column; gap: 1px; padding: 5px 4px 0 8px; min-width: 0; }
.rh-mode-name { font-family: var(--display); font-size: 17px; letter-spacing: 0.1em; line-height: 1; color: var(--bone); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rh-weather { font-family: var(--type); font-size: 8px; letter-spacing: 0.08em; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rh-weather i { font-style: normal; color: var(--amber); }
.rh-weather em { font-style: normal; color: var(--bone-dim); margin-left: 3px; }
.rh-pause {
  width: 42px; height: 42px; flex-shrink: 0; display: grid; place-items: center;
  background: rgba(10, 9, 9, 0.78); border: 1px solid rgba(232, 225, 210, 0.2);
  color: var(--bone); font-size: 11px; cursor: pointer; letter-spacing: 1px;
}
.rh-pause:hover { background: var(--rust); border-color: var(--amber); }

.rh-objective {
  position: absolute; top: calc(66px + var(--safe-top)); left: calc(10px + var(--safe-left));
  width: min(300px, 40vw); padding: 7px 10px 8px;
  background: linear-gradient(180deg, rgba(12, 10, 10, 0.78), rgba(12, 10, 10, 0.42));
  border-left: 2px solid var(--amber); backdrop-filter: blur(4px);
}
.rh-obj-label { font-family: var(--type); font-size: 7px; letter-spacing: 0.16em; color: var(--amber); }
.rh-obj-main { font-family: var(--display); font-size: 20px; letter-spacing: 0.04em; line-height: 1.05; }
.rh-objective .rh-bar { height: 4px; margin-top: 4px; background: rgba(232, 225, 210, 0.12); overflow: hidden; }
.rh-objective .rh-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--rust), var(--amber)); transition: width 0.25s; }
.rh-obj-sub { font-family: var(--type); font-size: 7px; letter-spacing: 0.08em; color: var(--muted); margin-top: 3px; }

.rh-minimap-wrap {
  position: absolute; top: calc(66px + var(--safe-top)); right: calc(10px + var(--safe-right));
  width: 118px; height: 118px; padding: 3px; background: rgba(8, 7, 7, 0.7);
  border: 1px solid rgba(232, 225, 210, 0.16); border-radius: 50%;
  backdrop-filter: blur(4px);
}
.rh-minimap-wrap canvas { width: 100%; height: 100%; border-radius: 50%; }
.rh-map-label {
  position: absolute; left: 50%; bottom: -8px; transform: translateX(-50%);
  font-family: var(--type); font-size: 6px; letter-spacing: 0.1em; color: var(--bone-dim);
  background: rgba(8, 7, 7, 0.85); padding: 2px 6px; border: 1px solid var(--line-soft); white-space: nowrap;
}

.rh-speedo {
  position: absolute; right: calc(12px + var(--safe-right)); bottom: calc(196px + var(--safe-bottom));
  width: 134px; display: flex; flex-direction: column; gap: 5px; align-items: stretch;
  padding: 8px 10px; background: linear-gradient(180deg, rgba(10, 9, 9, 0.85), rgba(10, 9, 9, 0.5));
  border: 1px solid rgba(232, 225, 210, 0.15); border-right: 2px solid var(--rust);
  backdrop-filter: blur(4px);
}
.rh-speed-num { display: flex; align-items: baseline; justify-content: flex-end; gap: 4px; }
.rh-speed-num b { font-family: var(--display); font-size: 38px; line-height: 0.8; letter-spacing: 0.01em; color: var(--bone); }
.rh-speed-num span { font-family: var(--type); font-size: 7px; letter-spacing: 0.1em; color: var(--muted); }
.rh-nitro, .rh-hull, .rh-special { display: grid; grid-template-columns: 40px 1fr; gap: 5px; align-items: center; }
.rh-nitro > span, .rh-hull > span, .rh-special > span {
  font-family: var(--type); font-size: 6px; letter-spacing: 0.06em; color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.rh-nitro-track, .rh-hull-track, .rh-special-track { height: 5px; background: rgba(232, 225, 210, 0.13); overflow: hidden; }
.rh-nitro-track i { display: block; height: 100%; width: 50%; background: linear-gradient(90deg, #22708a, var(--cyan)); }
.rh-hull-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #8d1318, #e0473c); transition: width 0.2s; }
.rh-hull-track i.danger { animation: dangerBlink 0.5s infinite; }
@keyframes dangerBlink { 50% { filter: brightness(2); } }
.rh-special > span { color: var(--amber); }
.rh-special-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #6c4a12, var(--amber)); }
.rh-special.ready .rh-special-track i { background: linear-gradient(90deg, #c07a1d, #ffe08a); box-shadow: 0 0 8px rgba(255, 210, 120, 0.7); }
.rh-special.ready > span { color: #ffe4af; text-shadow: 0 0 8px rgba(255, 200, 100, 0.8); }
.rh-special.active .rh-special-track i { background: linear-gradient(90deg, #fff, var(--amber)); animation: dangerBlink 0.6s infinite; }
.rh-special.active > span { color: #fff; }

/* touch controls: LEFT = turn pedals, RIGHT = five action pedals */
.rh-touch {
  position: absolute; left: calc(10px + var(--safe-left)); right: calc(10px + var(--safe-right));
  bottom: calc(10px + var(--safe-bottom));
  display: flex; justify-content: space-between; align-items: flex-end; gap: 10px;
  pointer-events: none;
}
.rh-steer { display: flex; gap: 8px; align-items: flex-end; pointer-events: auto; }
.rh-steer button {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  width: clamp(62px, 15vw, 88px); height: clamp(76px, 17vw, 98px);
  background: linear-gradient(160deg, rgba(40, 34, 32, 0.88), rgba(12, 10, 10, 0.8));
  border: 1px solid rgba(232, 225, 210, 0.25); border-bottom: 3px solid #5a4a40;
  color: var(--bone); cursor: pointer; backdrop-filter: blur(5px);
  clip-path: polygon(18% 0, 100% 0, 100% 82%, 82% 100%, 0 100%, 0 18%);
  transition: 0.08s; touch-action: none;
}
.rh-steer button b { font-family: var(--display); font-size: clamp(26px, 6vw, 34px); line-height: 0.8; }
.rh-steer button span { font-family: var(--type); font-size: 7px; letter-spacing: 0.13em; color: var(--muted); }
.rh-steer button.active, .rh-steer button:active {
  background: linear-gradient(160deg, #c05320, #7c2710); border-color: var(--amber);
  transform: translateY(2px) scale(0.97); box-shadow: 0 0 24px rgba(237, 164, 60, 0.3) inset;
}
.rh-steer button.active span { color: #ffe9d6; }

.rh-pedals { display: flex; flex-direction: column; gap: 7px; align-items: flex-end; pointer-events: auto; }
.rh-pedal-row { display: flex; gap: 7px; align-items: flex-end; }
.rh-pedals button {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  cursor: pointer; color: var(--bone); touch-action: none; position: relative; overflow: hidden;
  border: 1px solid rgba(232, 225, 210, 0.24); backdrop-filter: blur(5px);
  transition: 0.08s; text-shadow: 0 1px 4px rgba(0, 0, 0, 0.8);
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
}
.rh-pedals button b { font-family: var(--display); line-height: 0.85; letter-spacing: 0.02em; }
.rh-pedals button span { font-family: var(--type); font-size: 6px; letter-spacing: 0.06em; color: rgba(233, 226, 211, 0.75); white-space: nowrap; }
.rh-pedals button.active { transform: translateY(2px) scale(0.97); filter: brightness(1.3); }
.rh-nitro-btn, .rh-special-btn { width: clamp(64px, 15.5vw, 84px); height: clamp(44px, 10vw, 56px); }
.rh-nitro-btn { background: linear-gradient(160deg, rgba(28, 62, 74, 0.92), rgba(8, 18, 22, 0.85)); border-color: rgba(105, 216, 230, 0.55); border-bottom: 3px solid #2e7180; }
.rh-nitro-btn b { font-size: clamp(19px, 4.6vw, 25px); color: var(--cyan); }
