.rh-brake.active { background: linear-gradient(160deg, #b12924, #6d1013); box-shadow: 0 0 22px rgba(221, 43, 36, 0.4); }
.rh-handbrake { background: linear-gradient(160deg, rgba(58, 49, 44, 0.94), rgba(14, 12, 11, 0.9)); border-color: rgba(232, 225, 210, 0.35); border-bottom: 3px solid #5a4b41; }
.rh-handbrake b { font-size: clamp(15px, 3.8vw, 20px); color: var(--bone-dim); }
