.rh-warning {
  position: absolute; top: calc(66px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  font-family: var(--type); font-size: 8px; letter-spacing: 0.14em;
  color: #ffd2c8; background: rgba(80, 12, 14, 0.7); border: 1px solid rgba(221, 43, 36, 0.55);
  padding: 4px 10px; white-space: nowrap; max-width: 52vw; overflow: hidden; text-overflow: ellipsis;
}
.rh-warning:empty { display: none; }
.rh-toast {
  position: absolute; left: 50%; bottom: calc(190px + var(--safe-bottom)); transform: translate(-50%, 12px);
  font-family: var(--display); font-size: clamp(18px, 3vw, 26px); letter-spacing: 0.08em;
