  14%, 70% { opacity: 1; transform: translate(-50%, 0); }
  100% { opacity: 0; transform: translate(-50%, -10px); }
}
.rh-flash { position: absolute; inset: 0; background: #fff; opacity: 0; pointer-events: none; mix-blend-mode: screen; }
.rh-flash.on { animation: flash 0.3s ease; }
@keyframes flash { 0% { opacity: 0.6; } 100% { opacity: 0; } }

